// Ladin Ormanı — 3. sınıf Türkçe haftalık çalışma kâğıtları (MEB 2026-2027 taslak yıllık planı, TYMM).
// 2. sınıfla aynı düzen: özgün metin (250-330 sözcük) · anlama · o haftanın dil bilgisi · planlı yazma.
// Bileşenler turkce2.js'den gelir (A); 3. sınıfa özgü olanlar burada. Resim henüz yoksa metin resimsiz çıkar (resimVar).
// Üretim: node kaynak/calisma-kagitlari/uret.js t3   (tek hafta: t3:hafta-05)
module.exports = ({ etk, resim, numarala, resimVar, A, M }) => {
  const { harita, sirala, dogruYanlis, sozcuk, soru, tren, dogruYazim, yeniden, domino, yazma, eslestir, bosluk, kimlik, siniflandir, tablo, fikir, mesaj, kiyas, yonergeYaz, cizgi } = A;
  const metin = o => A.metin(Object.assign({}, o, { resimler: (o.resimler || []).filter(resimVar) }));
  // 3. sınıfa özgü
  const anaFikir = (secenekler, dogru) => etk(0, 'Metnin ana fikri hangisi? Doğru olanı daire içine al. Sonra nedenini yaz.',
    `<div class="t3-sec">${secenekler.map(s => `<span class="ttkb">${s}</span>`).join('')}</div><p class="ttkb t3-not">Çünkü</p>${cizgi(2)}`);
  const gercekMecaz = (liste) => etk(0, 'Altı çizili sözcük gerçek anlamında mı, mecaz anlamında mı kullanılmış? Doğru kutuyu işaretle.',
    `<div class="t3-gm">${liste.map(s => `<div><p class="ttkb">${s}</p><span class="ttkb"><i></i>gerçek</span><span class="ttkb"><i></i>mecaz</span></div>`).join('')}</div>`);
  const dilekce = (yonerge, kime, konu) => etk(0, yonerge,
    `<div class="t3-dilekce ttkb"><p class="t3-sag">Tarih: ……/……/20……</p><p class="t3-orta">${kime}</p>${cizgi(6)}<p class="t3-sag">Ad soyad: ………………………<br>İmza:</p><p class="t3-konu">Konu: ${konu}</p></div>`);

  const T3 = {
    'hafta-01': { unite: 1, hafta: 1, baslik: 'Yeni Sınıf, Eski Dostlar', konu: 'Hatırlatma haftası · Büyük harf, kısaltma, noktalama', sayfalar: () => [
      metin({ baslik: 'Yeni Sınıf, Eski Dostlar', resimler: ['yeni-sinif', 'eski-defter'], tahmin: 'Sence okulun ilk günü bu sınıfta neler oluyor?', paragraflar: [
        'Eylül sabahı okul bahçesi bir arı kovanı gibi vızıldıyordu. Ece, çantasının askısını sıkıca tutarak üçüncü sınıfların koridoruna yürüdü. Sınıfları bu yıl üst kata taşınmıştı. Kapıyı açınca pencereden giren güneş, sıraların üstünde altın rengi şeritler çizdi.',
        '– Ece! diye bağırdı Mert. Bütün yaz seni bekledik!',
        'Arkadaşları etrafını sardı. Zeynep yazın dedesinin köyüne gitmiş, ilk kez inek sağmıştı. Mert, Antalya\'dan Ankara\'ya 480 km yol gitmiş, TBMM\'yi gezmişti. Can ise yüzme kursunda iki uzunluk yüzmeyi öğrenmişti.',
        'Öğretmenimiz Nur Hanım içeri girdiğinde herkes yerine oturdu. Masasına renkli bir kutu koydu.',
        '– Bu yıl bir “Sınıf Hatıra Kutusu” tutacağız, dedi. Her ay içine bir anı yazıp atacağız. Haziranda açtığımızda bir yılı yeniden yaşayacağız.',
        'Ece defterini açtı. Geçen yılın defterleri evde, rafta duruyordu; sayfalarında ilk yazdığı eğri büğrü cümleler vardı. Şimdi kalemini tutuşu bile değişmişti. İlk anısını özenle yazdı: “Bugün yeni sınıfımıza geldik. Eski dostlarımı çok özlemişim.” Cümlesine büyük harfle başladı, sonuna nokta koydu.',
        'Teneffüs zili çaldığında Nur Hanım kutuyu rafa yerleştirdi. Kutunun içinde şimdiden yirmi altı kâğıt vardı. Her biri bir çocuğun yeni yıla dair umuduydu.',
      ] }),
      numarala([harita(), dogruYanlis(['Sınıf bu yıl üst kata taşınmıştı.', 'Mert yazın İzmir\'e gitmişti.', 'Hatıra kutusu haziranda açılacak.', 'Ece ilk anısını yazarken noktalama işaretine dikkat etmedi.']),
        sozcuk([['Okul bahçesi bir arı kovanı gibi <u>vızıldıyordu</u>.', ['çok kalabalık ve sesliydi', 'bomboştu', 'sessizdi']], ['Her biri bir çocuğun yeni yıla dair <u>umuduydu</u>.', ['gelecekten beklediği güzel şey', 'korkusu', 'ödevi']]])]),
      numarala([yeniden('Büyük harf hatalarını düzelterek cümleleri yeniden yaz.', ['ece ile mert antalya\'da oturuyor.', 'öğretmenimiz nur hanım bize bir kutu getirdi.', 'yazın karadeniz\'e gittik.']),
        eslestir('Kısaltmaları açılımlarıyla eşleştir.', [['TBMM', 'kilometre'], ['km', 'Türkiye Büyük Millet Meclisi'], ['TDK', 'Millî Eğitim Bakanlığı'], ['MEB', 'Türk Dil Kurumu']], 11),
        tren('Noktalama trenleri! Son vagona uygun işareti koy.', ['Bütün yaz seni bekledik', 'Sen yazın nereye gittin', 'Ece defterini açtı', 'Ne güzel bir kutu'], ['.', '?', '!'])]),
      numarala([yazma('Sınıfın hatıra kutusuna atacağın ilk anıyı yaz. Yazını giriş, gelişme ve sonuç bölümleriyle planla.', ['Giriş: Ne anlatacaksın?', 'Gelişme: Neler oldu?', 'Sonuç: Ne hissettin?'], 12)]),
    ] },
    'hafta-02': { unite: 2, hafta: 2, baslik: 'Sözünün Eri', konu: 'Değerlerimizle yaşıyoruz · Ana fikir, iki nokta ve tırnak', sayfalar: () => [
      metin({ baslik: 'Sözünün Eri', resimler: ['soz-veren', 'oyuncak-tamir'], tahmin: '“Sözünün eri” olmak ne demek olabilir?', paragraflar: [
        'Cuma akşamı Kerem, alt kattaki Hasan Dede\'nin kapısını çaldı. Hasan Dede bahçesine elli fide dikecekti ama sırtı ağrıyordu.',
        '– Yarın sabah dokuzda gelirim, dedi Kerem. Fideleri birlikte dikeriz.',
        'Hasan Dede\'nin gözleri parladı:',
        '– Sağ ol evladım. Sözüne güveniyorum.',
        'O gece telefon çaldı. Arayan takım kaptanı Emre\'ydi: “Yarın saat dokuzda final maçı var. Sensiz kazanamayız!” Kerem\'in yüreği hop etti. Bütün yaz bu maç için çalışmışlardı.',
        'Gece boyunca döndü durdu. Bir yanda maç, öbür yanda Hasan Dede. Sabah babası mutfakta kahvaltı hazırlarken ona danıştı. Babası ekmeğini bölüp gülümsedi:',
        '– Bir söz, ağızdan çıkınca bir köprü olur oğlum. Karşıdaki insan o köprüden geçer. Köprüyü yıkarsan o kişi suya düşer.',
        'Kerem bir süre sustu. Sonra Emre\'ye bir mesaj yazdı: “Bugün Hasan Dede\'ye söz verdim. Maçın ikinci yarısına yetişmeye çalışacağım.”',
        'Saat tam dokuzda Hasan Dede\'nin kapısındaydı. Toprağı kazdılar, fideleri yerleştirdiler, can suyunu verdiler. Son fideyi diktiklerinde saat on biri geçiyordu. Kerem koşa koşa sahaya vardığında maç bitmek üzereydi. Takımı bir gol geriydi.',
        'Hakem son dakikada Kerem\'i oyuna aldı. Kerem topu kaptı, Emre\'ye uzun bir pas verdi. Emre topu ağlarla buluşturdu! Maç berabere bitti.',
        'Akşam Hasan Dede\'nin balkonundan bir tabak kurabiye uzandı. Tabağın altında küçük bir not vardı: “Sözünün eri olan çocuğa.”',
      ] }),
      numarala([harita(), anaFikir(['Futbol çok eğlenceli bir oyundur.', 'Verilen söz, zor da olsa tutulmalıdır.', 'Fideleri sabah dikmek gerekir.']),
        soru(['Babasının “köprü” benzetmesini kendi cümlelerinle açıkla.', 'Sen Kerem\'in yerinde olsan ne yapardın? Neden?'])]),
      numarala([yeniden('Konuşmaları iki nokta ve tırnak işaretiyle yeniden yaz.', ['Hasan Dede sözüne güvendiğini söyledi.', 'Emre sensiz kazanamayız dedi.', 'Babası bir söz köprü olur dedi.']),
        dogruYazim('Hangisi doğru yazılmış? Balonu boya.', [['Emre: “Gel!” dedi.', 'Emre “gel” dedi.'], ['Hasan Dede\'nin', 'Hasan Dedenin'], ['saat dokuzda', 'saat 9\'da']], 21),
        sozcuk([['Kerem\'in <u>yüreği hop etti</u>.', ['çok heyecanlandı', 'uyudu', 'hastalandı']]])]),
      numarala([yazma('Sözünü tuttuğun ya da tutamadığın bir anını anlat. O gün ne öğrendin?', ['Kime ne söz verdin?', 'Ne oldu?', 'Ne öğrendin?'], 12)]),
    ] },
    'hafta-03': { unite: 2, hafta: 3, baslik: 'Çitin İki Yanı', konu: 'Değerlerimizle yaşıyoruz · Eş anlamlı sözcükler, ana duygu', sayfalar: () => [
      metin({ baslik: 'Çitin İki Yanı', resimler: ['komsu-bahce', 'cit-kapisi'], tahmin: 'Bir çitin iki yanında yaşayan komşular arasında neler olabilir?', paragraflar: [
        'Zeynep\'in ailesi yaz sonunda bahçeli küçük bir eve taşındı. Bahçeyi yandaki evden alçak, beyaz bir çit ayırıyordu. Çitin öbür yanında Saniye Teyze otururdu. Saniye Teyze yaşlı, biraz da sert bakışlı bir kadındı. Bahçesi rengârenk çiçeklerle doluydu.',
        'Taşındıkları ikinci gün Zeynep\'in topu çitin üstünden uçtu ve saksılardan birini devirdi. Saksı kırıldı, sardunyalar toprağa saçıldı. Saniye Teyze pencereden başını uzattı:',
        '– Bu bahçe benim yirmi yıllık emeğim! dedi öfkeyle.',
        'Zeynep o gece uyuyamadı. Sabah erkenden harçlığıyla bir saksı aldı. Annesiyle birlikte sardunyaları yeni saksıya dikti ve çitin kenarına bıraktı. Saksının yanına bir not iliştirdi: “Özür dilerim. Bahçeniz çok güzel. Bana çiçek yetiştirmeyi öğretir misiniz?”',
        'Ertesi sabah çitin üstünde bir kese duruyordu. İçinde domates tohumları ve titrek bir yazıyla yazılmış bir not vardı: “Önce domatesle başla. Sabırlı ol.”',
        'O günden sonra çit bir sınır olmaktan çıktı, bir köprüye dönüştü. Zeynep her akşam domateslerini sularken Saniye Teyze çitin öbür yanından ona öğütler verdi. Ağustos geldiğinde Zeynep\'in ilk kırmızı domatesi olgunlaştı. Onu kopardı ve çitin üstünden uzattı.',
        '– Bu sizin, dedi. Tohumu siz verdiniz.',
        'Saniye Teyze domatesi aldı. Sert bakışları yumuşadı, gözleri doldu.',
        'Sonbaharda Zeynep\'in babası çite küçük bir kapı yaptı. Artık iki bahçe arasında gidip gelmek için kimsenin çitin üstünden uzanmasına gerek yoktu.',
      ] }),
      numarala([harita(), sirala(['Zeynep\'in topu saksıyı kırdı.', 'Zeynep yeni bir saksı alıp özür notu bıraktı.', 'Saniye Teyze domates tohumu gönderdi.', 'Zeynep ilk domatesini Saniye Teyze\'ye verdi.', 'Babası çite bir kapı yaptı.'], 31),
        soru(['Metnin ana duygusu nedir? (öfke, pişmanlık, dostluk…) Neden?', '“Çit bir köprüye dönüştü.” cümlesi ne anlatıyor?'])]),
      numarala([domino('Eş anlam dominosu! Her taşın boş yarısına eş anlamlısını yaz.', ['yaşlı', 'öfke', 'armağan', 'sabır', 'cevap', 'kırmızı'], ['hediye', 'ihtiyar', 'kızgınlık', 'yanıt', 'al', 'dayanma gücü']),
        bosluk('Altı çizili sözcüğün eş anlamlısını kutudan seçip boşluğa yaz.', ['Saniye Teyze <u>yaşlı</u> bir kadındı. → ___ bir kadındı.', 'Zeynep\'in <u>yanıtı</u> onu sevindirdi. → Zeynep\'in ___ onu sevindirdi.', 'Bahçe <u>okul</u> gibi bir öğrenme yeriydi. → Bahçe ___ gibi bir öğrenme yeriydi.'], ['ihtiyar', 'cevabı', 'mektep'])]),
      numarala([yazma('Bir komşuna ya da arkadaşına özür notu yaz. Ne olduğunu, nasıl hissettiğini ve nasıl telafi edeceğini anlat.', ['Ne oldu?', 'Nasıl hissediyorsun?', 'Nasıl telafi edeceksin?'], 12)]),
    ] },
    'hafta-04': { unite: 2, hafta: 4, baslik: 'Sokağın Sessiz Sakinleri', konu: 'Değerlerimizle yaşıyoruz · Neden-sonuç, olayları kendi ifadeleriyle yazma', sayfalar: () => [
      metin({ baslik: 'Sokağın Sessiz Sakinleri', resimler: ['sokak-kedisi', 'barinak'], tahmin: 'Sokakta yaşayan hayvanlar için ne yapabiliriz?', paragraflar: [
        'Bizim sokağın sessiz sakinleri vardır: kediler, birkaç köpek, bir de çatıların kralı gibi gezen gri bir karga. Geçen yıla kadar onları pek fark etmezdim.',
        'Bir sabah okula giderken duvarın dibinde tir tir titreyen bir yavru kedi gördüm. Yağmur yağmıştı ve her yer çamurdu. Yavrunun gözleri yarı kapalıydı. Hemen annemi çağırdım. Annem kediyi bir havluya sardı ve veteriner olan komşumuz Aslı Abla\'ya götürdük. Aslı Abla yavruyu muayene etti:',
        '– Üşümüş ve aç kalmış, dedi. Sıcak bir yer ve mama ona iyi gelir.',
        'O gün bir karar verdim. Arkadaşlarım Deniz ve Bora ile sokağın köşesine bir “dostluk köşesi” kurmaya karar verdik. Apartman yöneticisinden izin aldık. Eski bir dolaptan yağmur geçirmeyen bir kulübe yaptık. Önüne bir su kabı ve bir mama kabı koyduk. Her sabah sırayla suyu tazeliyoruz.',
        'Bir hafta sonra köşeye topallayan bir köpek geldi. Arka ayağı yaralıydı. Ona yaklaşmadık çünkü korkmuş hayvanlar ürkebilir. Hemen belediyenin hayvan barınağını aradık. Ekip geldi, köpeği tedavi için götürdü.',
        'Ay sonunda barınağı ziyaret ettik. Bizim köpek iyileşmiş, kuyruğunu sallıyordu. Barınaktaki görevli bize sahiplenmenin bir sorumluluk olduğunu, hayvanların bakımının yıllar sürdüğünü anlattı.',
        'Şimdi sokağımızın sessiz sakinleri biraz daha mutlu. Biz de öyle. Çünkü bir hayvana yardım etmek, insanın kalbinde de bir köşe ısıtıyor.',
      ] }),
      numarala([harita(), dogruYanlis(['Yavru kedi soğuktan ve açlıktan titriyordu.', 'Çocuklar yaralı köpeği kucaklayıp eve götürdü.', 'Dostluk köşesi için yöneticiden izin aldılar.', 'Barınak görevlisi sahiplenmenin kolay olduğunu söyledi.']),
        soru(['Çocuklar yaralı köpeğe neden yaklaşmadı?', 'Son paragraftaki "kalbinde bir köşe ısıtmak" sözü ne anlatıyor?'])]),
      numarala([eslestir('Neden ve sonuç! Nedenleri sonuçlarıyla eşleştir.', [['Yavru kedi üşümüştü,', 'onu havluya sardılar.'], ['Köpek yaralıydı,', 'belediye barınağını aradılar.'], ['Kulübe yağmur geçirmiyordu,', 'kediler ıslanmadı.']], 41),
        bosluk('Cümleleri "çünkü" ya da "bu yüzden" ile tamamla.', ['Su kabını her sabah tazeliyoruz ___', 'Hayvanlara yardım etmek önemlidir ___', 'Köpek korkmuştu ___']),
        sirala(['Yavru kediyi buldum.', 'Veterinere götürdük.', 'Dostluk köşesini kurduk.', 'Barınağı ziyaret ettik.'], 42).replace('Olayları oluş sırasına göre numaralandır.', 'Olayları sıraya koy, sonra kendi cümlelerinle bir arkadaşına anlat.')]),
      numarala([yazma('Bir hayvana yardım ettiğin ya da yardım edilmesini gördüğün bir olayı kendi cümlelerinle anlat.', ['Hangi hayvan, nerede?', 'Ne oldu, ne yapıldı?', 'Sonunda ne oldu?'], 12)]),
    ] },
    'hafta-05': { unite: 2, hafta: 5, baslik: 'Ceviz Diken Dede', konu: 'Değerlerimizle yaşıyoruz · Zıt anlamlı sözcükler', sayfalar: () => [
      metin({ baslik: 'Ceviz Diken Dede', resimler: ['agac-diken', 'buyuk-ceviz'], tahmin: 'Yaşlı bir adam neden ağaç diker? Tahmin et.', paragraflar: [
        'Köyün girişinde, yol kenarında, beli bükük bir dede fidan dikiyordu. Elinde küçük bir kürek vardı; kürek her inişinde toprak yavaşça yarılıyordu. Yoldan geçen Ali durdu, merakla izledi.',
        '– Dede, ne dikiyorsunuz? diye sordu.',
        '– Ceviz, dedi dede, alnındaki teri silerek.',
        'Ali şaşırdı. Öğretmeni ceviz ağacının meyve vermesinin yıllar sürdüğünü anlatmıştı.',
        '– Ama dede, bu ağaç meyve verdiğinde siz… Belki göremezsiniz.',
        'Dede güldü. Yüzündeki kırışıklar güneşte derin derin göründü.',
        '– Haklısın evlat. Ben bu cevizden yemeyebilirim. Ama bak şuraya.',
        'Eliyle köyün meydanındaki kocaman ceviz ağacını gösterdi. Ağacın gövdesi o kadar kalındı ki üç çocuk el ele verse saramazdı. Gölgesinde köylüler çay içiyor, çocuklar oynuyordu.',
        '– O ağacı benim dedem dikmiş. Ben onun gölgesinde büyüdüm, cevizini yedim. Şimdi sıra bende. Ben dikeceğim, sen ve senin çocukların yiyecek.',
        'Ali bir süre sessiz kaldı. Sonra kovayı kaptı, çeşmeden su getirdi ve fidanın dibine döktü. Dede başını okşadı.',
        'Yıllar geçti. Ali büyüdü, köyden ayrıldı, şehirde öğretmen oldu. Bir yaz köye döndüğünde yol kenarındaki ceviz ağacı kocaman olmuştu. Gölgesinde küçük bir kız oturmuş, düşen cevizleri topluyordu.',
        '– Bu ağacı kim dikmiş? diye sordu kız.',
        'Ali gülümsedi. Cebinden bir ceviz fidanı çıkardı.',
        '– Gel, dedi. Önce birlikte bir tane dikelim, sonra anlatırım.',
      ] }),
      numarala([harita(), anaFikir(['Ceviz çok lezzetli bir meyvedir.', 'Bugün yaptığımız iyilikler gelecekteki insanlara ulaşır.', 'Ağaç dikmek çok yorucudur.']),
        soru(['Ali\'nin başta şaşırmasının nedeni neydi?', 'Metnin sonunda Ali ne yapmak istiyor? Neden?'])]),
      numarala([domino('Zıt anlam dominosu! Sözcükleri metinde bul, zıt anlamlısını yaz.', ['yaşlı', 'kalın', 'derin', 'geçmiş', 'sessiz', 'büyük'], ['ince', 'genç', 'sığ', 'küçük', 'gelecek', 'gürültülü']),
        yeniden('Altı çizili sözcüğün zıt anlamlısını kullanarak cümleyi yeniden yaz.', ['Dedenin beli <u>bükük</u>tü.', 'Ağacın gölgesi <u>serin</u>di.', 'Ali köyden <u>ayrıldı</u>.'])]),
      numarala([yazma('Senin gelecekteki insanlar için yapmak istediğin bir iyilik var mı? Bir yazı yaz.', ['Ne yapmak istiyorsun?', 'Kimlerin işine yarar?', 'Neden önemli?'], 12)]),
    ] },
    'hafta-06': { unite: 3, hafta: 6, baslik: 'Cepheden Bir Mektup', konu: 'Atatürk ve kahramanlarımız · Kısaltmalara gelen ekler, eş ve zıt anlam', sayfalar: () => [
      metin({ baslik: 'Cepheden Bir Mektup', resimler: ['eski-mektup', 'sehitlik'], tahmin: 'Bir asker cepheden annesine ne yazmış olabilir?', paragraflar: [
        'Geçen hafta dedemin evinde eski bir sandık açtık. Sandığın dibinde, sararmış bir zarfın içinde, dedemin dedesinin yazdığı bir mektup vardı. Mektubu 1915 yılında Çanakkale\'den, annesine yazmıştı. Babam onu yüksek sesle okudu:',
        '“Sevgili Anacığım, elini öperim. Bugün mavi denizin kıyısında, siperlerde bekliyoruz. Gece yıldızlar burada köydekinden daha parlak görünüyor. Arkadaşlarımla ekmeğimizi bölüşüyor, birbirimize köydeki türküleri söylüyoruz. Bazen çok üşüyoruz ama yüreğimiz sıcacık. Çünkü vatanımız için buradayız.',
        'Burada Seyit adında bir onbaşı tanıdım. Anlatılanlara göre o, top mermisini sırtına alıp topun namlusuna sürecek kadar güçlü ve cesur biriymiş. Herkes ondan güç alıyor.',
        'Anacığım, sen merak etme. Bahçedeki ceviz ağacını benim yerime sula. Kardeşime söyle, okulunu bırakmasın. Okumak, bu vatanı koruyacak en güçlü silahtır. Dualarını eksik etme. Oğlun Mehmet.”',
        'Babam mektubu bitirdiğinde odada derin bir sessizlik oldu. Ninem gözlerini sildi. Ben mektubun kenarındaki küçük lekeye baktım. Belki bir yağmur damlası, belki bir gözyaşıydı.',
        'O hafta okulda öğretmenimize mektubu anlattım. Öğretmenimiz bize Çanakkale Savaşı\'nı ve 18 Mart\'ı anlattı. Mehmet Dede ve arkadaşları gibi binlerce kişinin bu topraklar için canını verdiğini söyledi.',
        'Akşam ben de bir mektup yazdım. Kime mi? Mehmet Dede\'ye: “Sevgili dedem, mektubunu okudum. Ceviz ağacı hâlâ bahçede. Ben de okulumu hiç bırakmayacağım.”',
      ] }),
      numarala([harita(), dogruYanlis(['Mektup 1915 yılında yazılmıştı.', 'Mehmet mektubu kardeşine yazmıştı.', 'Mehmet okumayı en güçlü silah olarak görüyordu.', 'Anlatıcı da Mehmet Dede\'ye bir mektup yazdı.']),
        sozcuk([['Askerler <u>siperlerde</u> bekliyordu.', ['korunmak için kazılmış hendekler', 'gemiler', 'çadırlar']], ['<u>Yüreğimiz</u> sıcacık.', ['kalbimiz, içimiz', 'ellerimiz', 'evimiz']]])]),
      numarala([dogruYazim('Kısaltmalara gelen ekler kesme işaretiyle ayrılır ve kısaltmanın okunuşuna uyar. Doğrusunu boya.', [['TBMM\'ye', 'TBMM\'a'], ['TDK\'nin', 'TDK\'nın'], ['MEB\'e', 'MEB\'a'], ['km\'ye', 'km\'a']], 61),
        bosluk('Kısaltmalara uygun ekleri yaz. (Örnek: TBMM + de → TBMM\'de)', ['TBMM + de → ___', 'TDK + den → ___', 'MEB + in → ___', '5 km + lik → ___']),
        eslestir('Eş anlamlılarını eşleştir.', [['vatan', 'yürek'], ['kalp', 'yurt'], ['cesur', 'yanıt'], ['cevap', 'yiğit']], 62)]),
      numarala([yazma('Çanakkale\'de savaşan bir askere bir mektup yaz. Ona bugünkü Türkiye\'yi anlat.', ['Hitap:', 'Ona neler anlatacaksın?', 'Nasıl bir dilekle bitireceksin?'], 12)]),
    ] },
    'hafta-07': { unite: 3, hafta: 7, baslik: 'Herkes Okula!', konu: 'Atatürk ve kahramanlarımız · Karşılaştırma, zıt anlam, imza', sayfalar: () => [
      metin({ baslik: 'Herkes Okula!', resimler: ['millet-mektebi', 'harf-bloklari'], tahmin: 'Büyükler de okula gider mi? Ne öğrenmiş olabilirler?', paragraflar: [
        'Cumhuriyet Bayramı\'na bir hafta kala öğretmenimiz bir ödev verdi: “Ailenizdeki en yaşlı kişiye Cumhuriyet\'in ilk yıllarını sorun.”',
        'Ben de büyük ninem Hatice Nine\'ye sordum. Hatice Nine doksan yaşındaydı ama hafızası pırıl pırıldı. Gözlüğünü taktı, anlatmaya başladı:',
        '– Ben küçükken annem okuma yazma bilmezdi. Köyümüzde okuyabilen ancak birkaç kişi vardı. Hem eskiden kullanılan harfler öğrenmesi zor harflerdi.',
        '– Peki sonra ne oldu nine?',
        '– 1928 yılında Atatürk yeni harfleri getirdi. Bugün senin defterine yazdığın harfleri. Ardından her yerde “Millet Mektepleri” açıldı. Büyükler de akşamları okula gitmeye başladı. Annem kırk yaşındaydı. Gündüz tarlada çalışır, akşam elinde gaz lambasıyla okula giderdi.',
        'Hatice Nine durdu, gülümsedi:',
        '– Annemin ilk okuduğu kelime benim adımdı. Kara tahtaya “Hatice” yazmış, sonra sevinçten ağlamış. Eve gelince bana sarıldı, “Artık mektuplarını kendim okuyacağım.” dedi.',
        'Atatürk o yıllarda bir kara tahtanın başına geçip halka yeni harfleri kendisi öğretmiş. Bu yüzden ona “Başöğretmen” denirmiş.',
        'O akşam Hatice Nine benden bir şey istedi. Bir kâğıda adını ve soyadını yazdım, o da altına titrek eliyle imzasını attı. İmzasında küçük bir ay ile bir yıldız vardı.',
        '– Bunu bana annem öğretti, dedi. Her imzam ona bir teşekkürdür.',
      ] }),
      numarala([harita(), dogruYanlis(['Yeni harfler 1928 yılında kabul edildi.', 'Millet Mekteplerine yalnız çocuklar gidiyordu.', 'Hatice Nine\'nin annesi okumayı kırk yaşında öğrendi.', 'Atatürk\'e "Başöğretmen" denirdi.']),
        soru(['Hatice Nine\'nin annesi neden sevinçten ağladı?', 'İmzasındaki ay ve yıldız sence neyi anlatıyor?'])]),
      numarala([kiyas('Eskiden ve bugün okumayı öğrenmeyi karşılaştır.', 'Eskiden', 'Bugün'),
        domino('Zıt anlam dominosu! Metindeki sözcüklerin zıttını yaz.', ['yaşlı', 'zor', 'gündüz', 'ilk', 'sevinç', 'kara'], ['akşam', 'ak', 'genç', 'kolay', 'üzüntü', 'son']),
        etk(0, 'İmzanı tasarla! Adını ve soyadını yaz, altına sana özgü bir imza at.', `<div class="t3-imza"><div><span class="ttkb">Adım soyadım:</span>${cizgi(1)}</div><div><span class="ttkb">İmzam:</span><i></i></div></div>`)]),
      numarala([yazma('Ailendeki en yaşlı kişiyle bir söyleşi yap. Ona çocukluğunu sor ve öğrendiklerini yaz.', ['Kimle konuştun?', 'Çocukken okul nasıldı?', 'Seni en çok şaşırtan ne oldu?'], 12)]),
    ] },
    'hafta-08': { unite: 3, hafta: 8, baslik: 'Karda Bir Fener', konu: 'Atatürk ve kahramanlarımız · Yazışmayı sürdürme, iletileri karşılaştırma', sayfalar: () => [
      metin({ baslik: 'Karda Bir Fener', resimler: ['nene-hatun', 'kizilay-kamyon'], tahmin: 'Karlı bir gecede elinde fenerle yürüyen bu kadın kim olabilir?', paragraflar: [
        'Erzurum\'da kışlar çok sert geçer. 1877 yılının kasım ayında da kar dizleri aşıyordu. Şehir, uzun ve zorlu bir savaşın ortasındaydı.',
        'Bir gece düşman askerleri şehre yakın Aziziye Tabyası\'nı ele geçirdi. Tabya, şehri koruyan büyük bir kaleydi. Haber şehre yayılınca çan sesleri, davul sesleri birbirine karıştı. Uykudan uyanan halk, ellerinde ne varsa alıp sokağa döküldü.',
        'Kalabalığın arasında genç bir kadın vardı: Nene Hatun. Daha birkaç gün önce kardeşini savaşta kaybetmişti. Evde üç aylık bebeği uyuyordu. Bebeğini öptü, komşusuna emanet etti. Eline bir fener, beline kardeşinin kılıcını aldı ve karlı yokuşu tırmanan kalabalığa katıldı.',
        'Kadınlı erkekli, gençli yaşlı herkes tabyaya koştu. Kadınlar askerlere cephane ve su taşıdı, yaralıları sardı. Sabaha karşı tabya geri alındı. Erzurum kurtulmuştu.',
        'Nene Hatun o geceden sonra bir kahraman olarak anıldı. Uzun bir ömür yaşadı. Yaşlandığında çocuklar etrafına toplanır, ona o geceyi sorardı. O da hep aynı şeyi söylerdi:',
        '– Ben yalnız değildim. Herkes bir şey taşıdı: kimi fener, kimi su, kimi umut.',
        'Bugün Erzurum\'da Nene Hatun\'un adı bir caddede, bir okulda ve insanların kalbinde yaşıyor. Kızılay Haftası\'nda öğretmenimiz bize onu anlattığında anladım: Yardımlaşma bazen bir fener taşımak kadar küçük, bir şehri kurtarmak kadar büyüktür.',
      ] }),
      numarala([harita(), sirala(['Düşman Aziziye Tabyası\'nı ele geçirdi.', 'Nene Hatun bebeğini komşusuna emanet etti.', 'Halk tabyaya koştu.', 'Tabya geri alındı.', 'Nene Hatun yaşlanınca çocuklara anlattı.'], 81),
        soru(['Nene Hatun "Ben yalnız değildim." derken ne anlatmak istiyor?', 'Kızılay ile Nene Hatun\'un hikâyesi arasında nasıl bir bağ var?'])]),
      numarala([kiyas('Nene Hatun\'un o geceki yardımı ile bugün Kızılay\'ın yaptığı yardımları karşılaştır.', 'Nene Hatun', 'Kızılay'),
        mesaj('Bir arkadaşın Nene Hatun\'u merak edip sana yazdı. Yazışmayı sürdür: Cevap ver ve ona bir soru sor.', 'Merhaba! Öğretmen bugün Nene Hatun\'dan bahsetti ama ben kaçırdım. O kimdi, ne yapmıştı?')]),
      numarala([yazma('Zor bir durumda birlikte çalışarak başarılan bir işi anlat (ailede, sınıfta, mahallede).', ['Ne oldu?', 'Kim ne taşıdı, ne yaptı?', 'Sonunda ne oldu?'], 12)]),
    ] },
    'hafta-09': { unite: 3, hafta: 9, baslik: 'Çankaya\'da Bir Bahçe', konu: 'Atatürk ve kahramanlarımız · Sınıflandırma', sayfalar: () => [
      metin({ baslik: 'Çankaya\'da Bir Bahçe', resimler: ['cicek-buketi', 'eski-calisma-masasi'], tahmin: 'Atatürk çocuklarla nasıl vakit geçirirdi? Tahmin et.', paragraflar: [
        'Atatürk çocukları çok severdi. Onlarla konuşmak, sorularını dinlemek, onları güldürmek ona büyük mutluluk verirdi. Hayatında birkaç çocuğu evlat edindi. Bunlardan en küçüğü Ülkü\'ydü.',
        'Ülkü, Atatürk\'ün yanına geldiğinde çok küçüktü. Ankara\'da, Çankaya Köşkü\'nün bahçesinde koşup oynardı. Atatürk yorucu bir günün ardından bahçeye çıktığında Ülkü hemen yanına koşar, elinden tutar, ona topladığı çiçekleri verirdi. Atatürk o çiçekleri çalışma masasındaki bir bardağa koyardı.',
        'Çalışma odası kitaplarla doluydu. Atatürk çok kitap okurdu. Tarih, dil, matematik, coğrafya… Okuduğu kitapların kenarlarına notlar alır, önemli yerlerin altını çizerdi. Kitaplığında binlerce kitap vardı.',
        'Bir gün Ülkü masaya tırmanıp bir kitabı açmaya çalıştı. Kitap ağırdı, düştü. Ülkü korkuyla Atatürk\'e baktı. Atatürk kitabı yerden aldı, Ülkü\'yü kucağına oturttu ve kitaptaki resimleri birlikte incelediler.',
        '– Kitaplar düşerse kaldırırız, dedi Atatürk. Ama hiç açılmazsa içindekiler sonsuza kadar karanlıkta kalır.',
        'Atatürk, 23 Nisan\'ı dünya çocuklarına armağan etti. Bugün her 23 Nisan\'da farklı ülkelerden çocuklar Türkiye\'ye gelir, bayramı birlikte kutlar. Onun çocuklara verdiği değerin en güzel göstergesi, belki de budur.',
        'Atatürk 10 Kasım 1938\'de aramızdan ayrıldı. Biz onu her yıl saygıyla anıyoruz. Ama onu en iyi, onun gibi kitap okuyarak ve merak ederek anabiliriz.',
      ] }),
      numarala([harita(), dogruYanlis(['Ülkü, Atatürk\'ün evlat edindiği çocuklardandı.', 'Atatürk kitaplarına hiç not almazdı.', 'Atatürk 23 Nisan\'ı dünya çocuklarına armağan etti.', 'Ülkü kitabı düşürünce Atatürk ona kızdı.']),
        soru(['Atatürk\'ün "Hiç açılmazsa içindekiler karanlıkta kalır." sözü ne anlatıyor?'])]),
      numarala([siniflandir('Metindeki sözcükleri sınıflandır: kişi mi, yer mi, nesne mi?', [['Kişiler', '#3a86ff'], ['Yerler', '#12b886'], ['Nesneler', '#f2546b']], ['Ülkü', 'Ankara', 'kitap', 'Atatürk', 'Çankaya Köşkü', 'bardak', 'çiçek', 'bahçe', 'öğretmen']),
        tablo('Atatürk hakkında öğrendiklerini sınıflandırarak yaz.', ['Sevdiği şeyler', 'Yaptığı işler'], [['', ''], ['', ''], ['', '']])]),
      numarala([yazma('Atatürk\'e bir mektup yaz. Ona okuduğun en güzel kitabı anlat.', ['Hitap:', 'Hangi kitap, ne anlatıyor?', 'Kapanış:'], 12)]),
    ] },
    'hafta-10': { unite: 4, hafta: 10, baslik: 'Leyleklerin Uzun Yolu', konu: 'Doğayı tanıyoruz · Eş anlamlı sözcükleri kullanma, sınıflandırma', sayfalar: () => [
      metin({ baslik: 'Leyleklerin Uzun Yolu', resimler: ['leylekler', 'leylek-yuva'], tahmin: 'Leylekler kışın nereye gider? Tahmin et.', paragraflar: [
        'Dedemin köyünde, eski değirmenin bacasının tepesinde kocaman bir leylek yuvası vardır. Yuva, dallardan, otlardan ve çamurdan yapılmıştır. Dedem bu yuvanın, kendisi çocukken de orada olduğunu söyler.',
        'Her yıl mart ayının sonunda leylekler gökyüzünde belirir. Önce bir tane gelir, yuvayı onarır. Birkaç gün sonra eşi gelir. Gagalarını takırdatarak birbirlerini selamlarlar. Köyde herkes bilir: Leylekler geldiyse bahar da gelmiştir.',
        'Yazın yuvada iki üç yavru büyür. Anne ve baba leylek bütün gün tarlalarda, dere kenarlarında yiyecek arar. Kurbağa, böcek, küçük balık yakalar ve yavrularına getirir. Yavrular önce yuvanın kenarında kanat çırparak uçmayı dener. Sonra bir gün cesaretlerini toplar ve havalanırlar.',
        'Ağustos sona ererken köyün üstünde yüzlerce leylek toplanır. Gökyüzünde daireler çizer, sıcak hava akımlarına binerek yükselirler. Sonra hep birlikte güneye, Afrika\'ya doğru uzun bir yolculuğa çıkarlar. Bu yolculuk binlerce kilometre sürer.',
        'Leylekler yollarını nasıl bulur? Bilim insanları onların güneşi, dağları, nehirleri ve denizleri işaret olarak kullandığını düşünüyor. En şaşırtıcısı da şu: Leylekler baharda yine aynı yuvaya döner.',
        'Geçen bahar dedem bana bir dürbün verdi. Değirmenin yanında saatlerce bekledim. Sonunda gökyüzünde bir nokta belirdi. Nokta büyüdü, büyüdü… Bembeyaz kanatlarını açan bir leylek, bacadaki yuvaya süzülerek kondu. Dedem gülümsedi:',
        '– Hoş geldin, eski dost.',
      ] }),
      numarala([harita(), dogruYanlis(['Leylek yuvası dallardan, otlardan ve çamurdan yapılır.', 'Leylekler kışı köyde geçirir.', 'Leylekler baharda aynı yuvaya döner.', 'Leylekler yolculukta güneşi işaret olarak kullanabilir.']),
        sozcuk([['Leylekler <u>sıcak hava akımlarına</u> binerek yükselir.', ['yukarı doğru çıkan ılık hava', 'yağmur bulutları', 'deniz dalgaları']], ['Yavrular <u>cesaretlerini toplar</u> ve havalanır.', ['korkularını yener', 'tüylerini toplar', 'uyur']]])]),
      numarala([yeniden('Altı çizili sözcüğün yerine eş anlamlısını yazarak cümleyi yeniden yaz.', ['Leylekler <u>uzun</u> bir <u>yolculuğa</u> çıkar. (sefer)', 'Dedem bana bir <u>armağan</u> verdi.', 'Leylek <u>yanıt</u> verir gibi gagasını takırdattı.']),
        siniflandir('Leyleğin besinlerini ve yuvasının malzemelerini ayır.', [['Besin', '#f4a100'], ['Yuva malzemesi', '#8e5b2b']], ['kurbağa', 'dal', 'böcek', 'ot', 'balık', 'çamur'])]),
      numarala([yazma('Göç eden bir hayvanı araştır (kırlangıç, turna, somon…). Onun yolculuğunu anlatan bilgilendirici bir yazı yaz.', ['Hangi hayvan?', 'Nereden nereye göç eder?', 'Yolunu nasıl bulur?'], 12)]),
    ] },
    'hafta-11': { unite: 4, hafta: 11, baslik: 'Arıların Dansı', konu: 'Doğayı tanıyoruz · Ayrıntılı yönerge, yazma planı', sayfalar: () => [
      metin({ baslik: 'Arıların Dansı', resimler: ['ari-dans', 'ari-kovan'], tahmin: 'Arılar birbirleriyle nasıl anlaşır? Tahmin et.', paragraflar: [
        'Teyzem arıcıdır. Yazın onun yanına gittiğimde bana bir arıcı şapkası verdi. Şapkanın önünde ince bir tül vardı. Kovanların yanına yavaşça yaklaştık. Teyzem kapaklardan birini açtı ve altın renkli bir petek çıkardı.',
        '– Dikkatle bak, dedi. Şu arı dans ediyor.',
        'Gerçekten de bir arı peteğin üstünde garip bir şekilde dönüyordu. Önce düz bir çizgide kıpır kıpır ilerliyor, sonra sağa dönüp başlangıç noktasına geliyor, sonra yine düz çizgide ilerleyip bu kez sola dönüyordu. Sanki sekiz rakamı çiziyordu.',
        '– Bu, “sallanma dansı”, dedi teyzem. Bu arı çiçek dolu bir yer bulmuş. Dansıyla arkadaşlarına çiçeklerin yönünü ve uzaklığını anlatıyor. Çizgi ne kadar uzunsa çiçekler o kadar uzaktadır.',
        'Arkadaşları dans eden arının etrafına toplanmıştı. Antenleriyle ona dokunuyor, üzerindeki çiçek kokusunu alıyorlardı. Birkaç dakika sonra hepsi aynı yöne uçtu.',
        'Teyzem bana bir kovanda binlerce arı olduğunu anlattı. Kraliçe arı yumurta yumurtlar. İşçi arılar petek örer, bal yapar, yavrulara bakar, kovanı korur. Hepsinin bir görevi vardır.',
        '– Bir kaşık bal için yüzlerce arı bütün yaz çalışır, dedi teyzem.',
        'O akşam kahvaltılık balı kavanoza koyarken onu hiç olmadığı kadar değerli buldum. Kavanozun içinde sanki yüzlerce küçük dans vardı.',
      ] }),
      numarala([harita(), soru(['Sallanma dansında çizginin uzunluğu neyi gösterir?', 'İşçi arıların görevleri nelerdir?', 'Son cümle ne anlatıyor?']),
        sozcuk([['Arılar <u>petek örer</u>.', ['balmumundan altıgen gözler yapar', 'çiçek toplar', 'uyur']]])]),
      numarala([yonergeYaz('Ayrıntılı yönerge! Arıcıların kovanı nasıl açtığını teyzenin anlatımından yola çıkarak adım adım yaz. Her adımda neye dikkat edileceğini de ekle.', 5),
        etk(0, 'Metnin devamını sen yaz: Ertesi gün teyzenle birlikte bal hasadına çıktınız. Neler oldu?', cizgi(5))]),
      numarala([yazma('"Arılar neden önemlidir?" konulu bilgilendirici bir yazı yaz. Önce yazma planını doldur.', ['Giriş: Arılar kimdir?', 'Gelişme: Ne iş yaparlar? Bize ve doğaya faydaları?', 'Sonuç: Arıları nasıl koruyabiliriz?'], 12)]),
    ] },
    'hafta-12': { unite: 4, hafta: 12, baslik: 'Dere Neden Kurudu?', konu: 'Doğayı tanıyoruz · Ana fikir, okumayı değerlendirme', sayfalar: () => [
      metin({ baslik: 'Dere Neden Kurudu?', resimler: ['kuru-nehir', 'akan-dere'], tahmin: 'Bir dere neden kurur? Tahmin et.', paragraflar: [
        'Köyümüzün kenarından küçük bir dere akardı. Yazın ayaklarımızı serin suyuna sokar, taşların arasında küçük balıkları izlerdik. Bu yaz köye gittiğimizde dere yoktu. Yerinde çatlak çatlak bir toprak, birkaç kuru saz ve bir balık iskeleti vardı.',
        'Çok üzüldüm. Dedeme sordum:',
        '– Dere nereye gitti dede?',
        'Dedem derin bir nefes aldı:',
        '– Bu yıl çok az kar yağdı, yağmur da yağmadı. Bir de herkes tarlasını dereden çektiği suyla sulamaya başladı. Kimi suyu gereğinden fazla kullandı. Dere yorgun düştü.',
        'O gün kuzenim Elif ile bir karar verdik. Köyün muhtarına gidip derenin kurumasını anlattık. Muhtar köylüleri camide topladı. Bir su uzmanı davet edildi. Uzman, damla sulama denen bir yöntemi anlattı. Bu yöntemde su, bitkinin köküne damla damla verilir; böylece çok daha az su harcanır.',
        'Köylüler önce tereddüt etti ama sonra birkaç tarlada denediler. Sonbaharda bu tarlaların ürünü diğerlerinden azalmamıştı ama çok daha az su kullanılmıştı. Ertesi yıl neredeyse bütün köy damla sulamaya geçti.',
        'Kışın bol kar yağdı. Bahar geldiğinde dedem bir video gönderdi: Dere yeniden akıyordu! Suyun şırıltısını telefondan bile duyabiliyordum.',
        'Yazın köye gittiğimde ilk iş dereye koştum. Ayaklarımı suya soktum. Küçük bir balık parmaklarımın arasından süzülüp geçti. Sanki bana teşekkür ediyordu.',
      ] }),
      numarala([harita(), anaFikir(['Yazın köyde dereye girmek eğlencelidir.', 'Doğal kaynakları dikkatli kullanırsak onları koruyabiliriz.', 'Damla sulama zor bir yöntemdir.']),
        sirala(['Dere kurudu.', 'Çocuklar muhtara gitti.', 'Bir su uzmanı damla sulamayı anlattı.', 'Köylüler damla sulamaya geçti.', 'Dere yeniden aktı.'], 121)]),
      numarala([eslestir('Neden ve sonuç!', [['Az kar ve yağmur yağdı,', 'su tasarruf edildi.'], ['Damla sulama kullanıldı,', 'dere kurudu.'], ['Kışın bol kar yağdı,', 'dere yeniden aktı.']], 122),
        tablo('Okumamı değerlendiriyorum. Bu metni okurken neler yaptın?', ['Okurken', 'Evet / Hayır'], [['Başlığa ve resimlere bakıp tahmin yaptım.', ''], ['Bilmediğim sözcüğün anlamını cümleden çıkardım.', ''], ['Noktalama işaretlerine dikkat ettim.', ''], ['Takıldığım yeri yeniden okudum.', '']])]),
      numarala([yazma('Okulunda ya da evinde suyu korumak için bir kampanya başlatıyorsun. Kampanya afişinin metnini yaz.', ['Kampanyanın adı:', 'Neden gerekli?', 'Herkes ne yapmalı?'], 12)]),
    ] },
    'hafta-13': { unite: 5, hafta: 13, baslik: 'Tilkinin İki Kürkü', konu: 'Doğayı tanıyoruz · Görsel okuma (tablo), yazma planı', sayfalar: () => [
      metin({ baslik: 'Tilkinin İki Kürkü', resimler: ['kutup-tilkisi', 'yaz-tilkisi'], tahmin: 'Bir hayvan mevsime göre renk değiştirebilir mi?', paragraflar: [
        'Dünyanın en soğuk yerlerinden birinde, kuzey kutbuna yakın karlı ovalarda küçük bir tilki yaşar: kutup tilkisi. Bu tilkinin bir sırrı vardır. Onun iki kürkü vardır; biri kış için, biri yaz için.',
        'Kışın kutup tilkisinin kürkü bembeyazdır. Bu beyaz kürk onu karın içinde neredeyse görünmez yapar. Kürkü o kadar sık ve kalındır ki sıcaklık sıfırın çok altına düştüğünde bile üşümez. Kulakları küçük, bacakları kısa, kuyruğu ise kocaman ve kabarıktır. Uyurken kuyruğunu bir battaniye gibi burnunun üstüne örter.',
        'Bahar gelip karlar erimeye başlayınca tilki yavaş yavaş tüy döker. Beyaz kürkün yerine kahverengi ve gri bir kürk çıkar. Artık kayaların, otların ve toprağın rengine benzer. Böylece yazın da kolayca saklanabilir.',
        'Peki tilki rengini neden değiştirir? Çünkü hem avlanırken hem de kendisini avlamak isteyen hayvanlardan korunurken saklanması gerekir. Doğada çevresine benzeyerek gizlenmeye kamuflaj denir.',
        'Kutup tilkisi kışın yiyecek bulmakta zorlanır. Bazen kutup ayılarını uzaktan izler ve ayının artıklarını yer. Yazın ise kuş yumurtası, küçük kemirgenler ve böceklerle beslenir. Yiyecek bol olduğunda bir kısmını karın altına saklar, kışın kullanır.',
        'Bilim insanları, iklim ısındıkça karın daha geç yağıp daha erken eridiğini söylüyor. Bu durumda beyaz kürklü tilki, karsız toprakta kolayca fark edilebilir. Doğanın bu küçük ustasını korumak, iklimi korumaktan geçiyor.',
      ] }),
      numarala([tablo('Metne göre tabloyu doldur.', ['', 'Kışın', 'Yazın'], [['Kürkünün rengi', '', ''], ['Nerede saklanır?', '', ''], ['Ne yer?', '', '']]),
        soru(['Kamuflaj ne demektir? Metinden bir örnek ver.', 'İklimin ısınması kutup tilkisini nasıl etkiler?'])]),
      numarala([kiyas('Kutup tilkisi ile çölde yaşayan bir hayvanı (deve, çöl tilkisi) karşılaştır.', 'Kutup tilkisi', 'Çöl hayvanı'),
        sozcuk([['Tilki karın içinde neredeyse <u>görünmez</u> olur.', ['zor fark edilir', 'çok parlak olur', 'kaybolur gider']], ['Yiyecek <u>bol</u> olduğunda saklar.', ['çok', 'az', 'soğuk']]])]),
      numarala([yazma('Bir hayvanın "iki mevsimini" anlatan bilgilendirici bir yazı yaz. Önce plan yap.', ['Hangi hayvan, nerede yaşar?', 'Kışın ve yazın ne değişir?', 'Neden değişir?'], 12)]),
    ] },
    'hafta-14': { unite: 5, hafta: 14, baslik: 'Ansiklopedideki Mektup', konu: 'Bilgi hazinemiz · Neden-sonuç, istek ve öneri yazma', sayfalar: () => [
      metin({ baslik: 'Ansiklopedideki Mektup', resimler: ['ansiklopedi', 'merakli-cocuk'], tahmin: 'Bir ansiklopediden mektup çıkarsa kimden olabilir?', paragraflar: [
        'Okul kütüphanemizin en üst rafında kalın, eski bir ansiklopedi takımı durur. Yirmi cilttir. Kimse onlara pek dokunmaz çünkü bugün her şeyi internetten arayabiliyoruz.',
        'Bir gün volkanları araştırmak için “V” harfiyle başlayan cildi indirdim. Sayfaları çevirirken arasından sararmış bir kâğıt düştü. Bir mektuptu bu. Tarihi 1987\'ydi.',
        '“Sevgili okuyucu, bu ansiklopediyi açtıysan meraklı birisin demektir. Ben bu okulun eski öğrencilerinden Sema\'yım. Bu ciltleri babam kütüphaneye bağışladı. Ben de içlerine on mektup sakladım. Her mektupta sana bir soru soruyorum. Hepsini bulursan, kütüphaneci sana bir hediyemi verecek. İlk sorum: Dünyanın en yüksek yanardağı hangisidir?”',
        'Hemen cevabı aramaya koyuldum. Ansiklopedide değil, internette aradım. Ama farklı siteler farklı cevaplar veriyordu! Kütüphaneci Okan Bey\'e sordum. Gülümsedi:',
        '– Bilgiyi aldığın kaynağın güvenilir olması çok önemlidir. Ansiklopediler uzmanlar tarafından yazılır ve kontrol edilir. İnternette de güvenilir kaynakları seçmeyi öğrenmeliyiz.',
        'Ansiklopediden cevabı buldum, sonra güvenilir bir bilim sitesinden kontrol ettim. Ertesi hafta arkadaşlarımla birlikte diğer ciltleri karıştırmaya başladık. Ansiklopedi rafı birden sınıfın en kalabalık yeri oldu.',
        'Bir ay sonra onuncu mektubu bulduk. Okan Bey bize bir kutu verdi. İçinde bir not ve yepyeni bir ansiklopedi takımı vardı. Not şöyleydi: “Bilgi paylaşınca çoğalır. Şimdi sıra sizde: Siz de gelecekteki okuyuculara bir mektup bırakın. Sevgilerle, Sema.”',
      ] }),
      numarala([harita(), eslestir('Neden ve sonuç!', [['Mektupta merak uyandıran sorular vardı,', 'ansiklopedi rafı kalabalıklaştı.'], ['İnternetteki siteler farklı cevaplar verdi,', 'kaynağı kontrol etmek gerekti.'], ['Bütün mektuplar bulundu,', 'çocuklara hediye verildi.']], 141),
        soru(['Okan Bey\'e göre ansiklopediler neden güvenilir kaynaktır?', 'Sema neden mektuplar saklamış olabilir?'])]),
      numarala([fikir('Bu düşünceye katılıyor musun?', 'İnternet varken ansiklopediye gerek yoktur.'),
        yazma('Okul müdürüne kütüphane için bir istek ve öneri mektubu yaz.', ['Hitap:', 'İsteğin ve önerin:', 'Kapanış ve ad soyad:'], 5)]),
      numarala([yazma('Gelecekteki okuyuculara bir mektup yaz ve ona bir soru sor. Mektubunu bir kitabın arasına saklayabilirsin.', ['Hitap:', 'Kendini tanıt ve soruyu sor:', 'Kapanış:'], 12)]),
    ] },
    'hafta-15': { unite: 5, hafta: 15, baslik: 'Sözlükte Bir Yolculuk', konu: 'Bilgi hazinemiz · Alfabetik sıra, sözlük kullanma', sayfalar: () => [
      metin({ baslik: 'Sözlükte Bir Yolculuk', resimler: ['sozluk-cocuk', 'kitaptan-sekiller'], tahmin: 'Sözlükte bir sözcük nasıl bulunur?', paragraflar: [
        'Murat masal kitabını okurken bir sözcükte takıldı: “Kervan, uzun bir yolculuğun sonunda hana ulaştı.” “Han” ne demekti? Ağabeyi yanından geçerken sordu.',
        '– Ağabey, han ne demek?',
        '– Sözlüğe bak, dedi ağabeyi. Bulmak, söylemekten daha eğlenceli.',
        'Murat raftaki kalın sözlüğü indirdi. Sayfaları rastgele çevirmeye başladı ama sözcük bir türlü çıkmıyordu. Ağabeyi gülümseyerek yanına oturdu.',
        '– Sözlükte sözcükler alfabe sırasına göre dizilir. “Han” h ile başlıyor. Önce “H” bölümünü bul.',
        'Murat \'H\' bölümünü buldu. Sonra ağabeyi ikinci harfe bakmasını söyledi. “Ha” ile başlayan sözcükler, “He” ile başlayanlardan önce gelirdi. Sayfaların üst köşesindeki kılavuz sözcükler de ona yol gösterdi. Birkaç saniye içinde aradığını buldu:',
        '“han: Eskiden yolcuların ve kervanların konakladığı büyük yapı.”',
        'Murat\'ın gözleri parladı. Ama sözlük onu bırakmadı. “Han”ın hemen yanında “hançer”, onun yanında “hangar” vardı. Merakla onları da okudu. Sonra “hangar”ın anlamında geçen “uçak” sözcüğüne baktı. Böyle böyle bir sözcükten diğerine atlayarak sözlükte uzun bir yolculuğa çıktı.',
        'Akşam yemeğinde babasına sordu:',
        '– Baba, biliyor musun, hangar uçakların evi demekmiş!',
        'Babası şaşırdı:',
        '– Bunu nereden öğrendin?',
        '– Bir kervandan başladım, bir uçakta bitirdim, dedi Murat gülerek.',
      ] }),
      numarala([harita(), soru(['Murat sözcüğü önce neden bulamadı?', 'Ağabeyi ona hangi ipuçlarını verdi?', '"Bir kervandan başladım, bir uçakta bitirdim." sözü ne anlatıyor?'])]),
      numarala([etk(0, 'Sözlük sırası! Sözcükleri alfabetik sıraya göre numaralandır.', `<div class="t3-sirala ttkb">${['hangar', 'han', 'hançer', 'kervan', 'harita', 'göl'].map(s => `<span><i></i>${s}</span>`).join('')}</div>`),
        etk(0, 'Sözlükte bul! Bu sözcüklerin anlamlarını sözlükten bulup yaz.', `<div class="t3-sozluk ttkb">${['kervan', 'konaklamak', 'hangar'].map(s => `<div><b>${s}:</b>${cizgi(1)}</div>`).join('')}</div>`)]),
      numarala([yazma('Sözlükte rastgele bir sayfa aç. Daha önce bilmediğin üç sözcük seç ve her biriyle birer cümle yaz.', ['1. sözcük ve cümlesi:', '2. sözcük ve cümlesi:', '3. sözcük ve cümlesi:'], 10)]),
    ] },
    'hafta-16': { unite: 5, hafta: 16, baslik: 'Enerji Avcıları', konu: 'Bilgi hazinemiz · Dilekçe yazma', sayfalar: () => [
      metin({ baslik: 'Enerji Avcıları', resimler: ['enerji-avcilari', 'gunes-paneli'], tahmin: 'Enerji avcıları ne avlar? Tahmin et.', paragraflar: [
        'Enerji Tasarrufu Haftası\'nda sınıfımız “Enerji Avcıları” kulübünü kurdu. Görevimiz okulda boşa harcanan enerjiyi bulmaktı. Her birimize bir kontrol listesi verildi.',
        'İlk gün koridorlarda dolaştık. Pencerelerden bol ışık girdiği hâlde lambaların yandığını fark ettik. Spor salonunda kimse yokken bütün ışıklar açıktı. Öğretmenler odasında bir bilgisayar ekranı bütün gece açık kalmıştı. Kontrol listemiz kısa sürede doldu.',
        'Bulduklarımızı bir tabloya döktük. Okulun bir aylık elektrik faturasını gördüğümüzde hepimiz şaşırdık. Öğretmenimiz Selin Hanım, enerjinin büyük kısmının fosil yakıtlardan, yani kömür ve petrolden üretildiğini anlattı. Bu yakıtlar havayı kirletiyor ve bir gün tükenecekti.',
        '– Peki güneşten enerji üretemez miyiz? diye sordu Defne.',
        '– Üretebiliriz, dedi Selin Hanım. Güneş panelleri güneş ışığını elektriğe çevirir. Güneş hiç tükenmeyen bir enerji kaynağıdır.',
        'O gün bir fikir doğdu: Okulumuzun çatısına güneş paneli koydurmak! Ama bunu nasıl yapacaktık? Selin Hanım bize dilekçe yazmayı öğretti. Dilekçe, resmî bir kuruma isteğimizi saygılı ve düzenli bir şekilde yazmamızı sağlayan bir yazıydı.',
        'Hep birlikte okul müdürümüze bir dilekçe yazdık. İçine enerji avımızın sonuçlarını, güneş panelinin faydalarını ve önerilerimizi ekledik. Sınıfın tamamı imzaladı.',
        'Bir hafta sonra müdürümüz sınıfımıza geldi. Dilekçemizi belediyeye iletmişti. Belediye, okulumuzu güneş paneli projesine almıştı! O gün kendimizi gerçek avcılar gibi hissettik. Avladığımız şey, boşa giden enerjiydi.',
      ] }),
      numarala([harita(), dogruYanlis(['Spor salonunda kimse yokken ışıklar açıktı.', 'Fosil yakıtlar hiç tükenmez.', 'Güneş paneli güneş ışığını elektriğe çevirir.', 'Dilekçeyi yalnız Defne imzaladı.']),
        soru(['Çocuklar okulda enerjinin boşa harcandığı hangi yerleri buldu?', 'Dilekçe ne işe yarar?'])]),
      numarala([dilekce('Sen de okul müdürüne bir dilekçe yaz. Okulda değişmesini istediğin bir şeyi saygılı bir dille iste.', 'OKUL MÜDÜRLÜĞÜNE', 'Okulumuzla ilgili bir istek')]),
      numarala([yazma('Evinde bir "enerji avı" yap. Bulduklarını ve önerilerini anlatan bir rapor yaz.', ['Nerede enerji boşa gidiyordu?', 'Ne öneriyorsun?', 'Ailen önerilerine ne dedi?'], 12)]),
    ] },
    'hafta-17': { unite: 5, hafta: 17, baslik: 'Kütüphanede Bir Gece', konu: 'Bilgi hazinemiz · Yazışmayı başlatma, sürdürme, sonlandırma; hataları düzeltme', sayfalar: () => [
      metin({ baslik: 'Kütüphanede Bir Gece', resimler: ['gece-kutuphane', 'fener-okuma'], tahmin: 'Bir gece kütüphanede kalsan neler olurdu?', paragraflar: [
        'Şehir kütüphanesi yılda bir kez “Kütüphanede Bir Gece” etkinliği düzenler. Bu yıl bizim sınıf seçildi! Uyku tulumlarımızı, fenerlerimizi ve en sevdiğimiz kitapları alıp akşam yedide kütüphanenin önünde toplandık.',
        'Kütüphaneci Leyla Hanım bizi büyük salona aldı. Raflar tavana kadar uzanıyordu. Işıkları kıstığında salon bir anda gizemli bir mağaraya dönüştü. Sadece fenerlerimizin ışıkları kitapların sırtlarında dans ediyordu.',
        'İlk etkinlik bir hazine avıydı. Leyla Hanım bize ipuçları verdi: “Ben bir masal kitabıyım ama içimde ejderha yok. Sırtım kırmızı, üçüncü raftayım.” Kitapları bulmak için katalog numaralarını okumayı öğrendik.',
        'Sonra her birimiz uyku tulumuna girip fenerle kitap okuduk. Ben bir kâşif kitabı okudum. Gece yarısına doğru gözlerim kapanırken kitabın kahramanıyla birlikte buzlu dağlara tırmandığımı hayal ettim.',
        'Sabah olunca Leyla Hanım bize bir sürpriz yaptı. Her birimize bir mektup arkadaşı verdi. Bunlar başka bir şehirdeki kütüphanede aynı geceyi yaşayan çocuklardı. Onlara bir ileti yazacaktık.',
        'Ben, Van\'da yaşayan Aras\'a yazdım: “Merhaba Aras! Ben Deniz. Dün gece kütüphanede kaldık, sen de kaldın mı? En çok hangi kitabı sevdin?” Aras ertesi gün cevap verdi. O gece bir uzay kitabı okumuş. Şimdi her hafta birbirimize okuduğumuz kitapları yazıyoruz.',
        'Eve dönerken annem sordu: “Kütüphanede bir gece nasıldı?” Ona şöyle dedim: “Bir gecede yüz dünya gezdim, bir de yeni bir arkadaş edindim.”',
      ] }),
      numarala([harita(), soru(['Kütüphane karanlıkta neye benzetiliyor?', 'Çocuklar hazine avında kitapları nasıl buldu?', 'Deniz\'in son sözü ne anlatıyor?'])]),
      numarala([mesaj('Aras\'ın iletisine cevap ver. Yazışmayı sürdür ve uygun bir sözle sonlandır.', 'Merhaba Deniz! Ben de bir uzay kitabı okudum, çok sevdim. Sen kâşif kitabını bitirdin mi? Bana ne oldu anlatır mısın?'),
        yeniden('Hata avcısı! Her cümlede bir yazım ya da noktalama hatası var. Bul ve düzelterek yaz.', ['dün gece kütüphanede kaldık.', 'Sen de kaldınmı?', 'Leyla hanım bize sürpriz yaptı']),
        etk(0, 'Yazışmalarda hangi sözler nerede kullanılır? Doğru kutuya yaz: Merhaba, Görüşmek üzere, Nasılsın?, Sevgilerle, Bana da yazar mısın?', `<div class="t3-ucbolum ttkb">${['Başlatma', 'Sürdürme', 'Sonlandırma'].map(s => `<div><b>${s}</b>${cizgi(2)}</div>`).join('')}</div>`)]),
      numarala([yazma('Başka bir şehirdeki bir çocuğa ilk iletini yaz. Kendini tanıt, ona okuduğun bir kitabı anlat ve bir soru sor.', ['Başlatma (selam):', 'Sürdürme (kendini ve kitabını anlat):', 'Sonlandırma:'], 12)]),
    ] },
    'hafta-18': { unite: 5, hafta: 18, baslik: 'Pati İzleri', konu: 'Pekiştirme haftası · Eş-zıt anlam, kısaltma ekleri, büyük harf, yönerge', sayfalar: () => [
      metin({ baslik: 'Pati İzleri', resimler: ['pati-izleri', 'agactaki-kedi'], tahmin: 'Bu izler kimin olabilir? Nereye gidiyor olabilir?', paragraflar: [
        'Sabah bahçeye çıktığımızda çamurun üzerinde küçük, yuvarlak izler vardı. Kardeşim Mina hemen eğildi:',
        '– Bunlar Boncuk\'un pati izleri! Dün gece eve gelmedi.',
        'Boncuk, sokağımızın en meraklı kedisiydi. Turuncu tüyleri ve beyaz patileriyle herkes onu tanırdı. Ama dün akşamdan beri ortalıkta yoktu.',
        'İzleri takip etmeye karar verdik. İzler önce çiçek tarhının içinden geçti, sonra komşumuz Ayten Hanım\'ın çitinin altından süzüldü. Ayten Hanım pencereden seslendi:',
        '– Dün gece bahçede bir miyavlama duydum ama karanlıktı, göremedim.',
        'İzler parkın yanındaki büyük çınar ağacının dibinde bitiyordu. Başımızı kaldırdık. Boncuk en yüksek dallardan birinde, titreyerek bize bakıyordu! Belki bir köpekten kaçmış, ağaca tırmanmış ama inememişti.',
        'Mina ağlamaya başladı. Ben sakin kalmaya çalıştım. Annemi aradım. Annem itfaiyeyi aramamızı söyledi. 112\'yi arayıp adresi ve durumu anlattım. Görevli abla çok kibardı, ekibin yola çıktığını söyledi.',
        'On beş dakika sonra kırmızı itfaiye aracı parkın önüne geldi. İtfaiyeci Kerem Bey uzun bir merdiveni ağaca dayadı, yavaşça tırmandı ve Boncuk\'u kucağına aldı. Aşağı indiğinde Boncuk Mina\'nın kollarına atladı ve mırıldanmaya başladı.',
        'O akşam Mina bir resim çizdi: Ağaç, merdiven, itfaiyeci ve Boncuk. Resmin altına kocaman harflerle yazdı: “TEŞEKKÜRLER KEREM BEY!” Ertesi gün resmi itfaiye istasyonuna götürdük. Şimdi resmimiz istasyonun duvarında asılı duruyor.',
      ] }),
      numarala([harita(), sirala(['Bahçede pati izleri bulundu.', 'Ayten Hanım miyavlama duyduğunu söyledi.', 'Boncuk ağaçta bulundu.', '112 arandı.', 'İtfaiyeci Boncuk\'u kurtardı.'], 181),
        soru(['Anlatıcı neden sakin kalmaya çalıştı?', '112\'yi ararken hangi bilgileri verdi?'])]),
      numarala([domino('Eş ve zıt anlam karışık! Her taşın yanına ister eş ister zıt anlamlısını yaz ve hangisi olduğunu belirt (E / Z).', ['yüksek', 'kibar', 'sakin', 'büyük', 'yavaş', 'cevap'], ['alçak', 'nazik', 'telaşlı', 'iri', 'hızlı', 'yanıt']),
        yeniden('Büyük harf ve kısaltma eklerini düzelterek yeniden yaz.', ['mina ile ayten hanım boncuk\'u aradı.', 'İtfaiyeyi 112ye bildirdik.']),
        yonergeYaz('Kaybolan bir evcil hayvanı bulmak için ayrıntılı bir yönerge yaz.', 4)]),
      numarala([yazma('İtfaiyeci Kerem Bey\'e bir teşekkür mektubu yaz.', ['Hitap:', 'Ne için teşekkür ediyorsun?', 'Kapanış:'], 12)]),
    ] },
    'hafta-19': { unite: 6, hafta: 19, baslik: 'Karne ve Kitap', konu: 'Hatırlatma haftası · Okuma amacı ve stratejisi, sınıflandırma', sayfalar: () => [
      metin({ baslik: 'Karne ve Kitap', resimler: ['karne-gunu', 'tatil-okuma'], tahmin: 'Karne günü öğretmen öğrencilerine ne hediye etmiş olabilir?', paragraflar: [
        'Karne günü sınıfta bir heyecan vardı. Öğretmenimiz Nur Hanım karnelerimizi tek tek dağıttı. Ama her karnenin yanında bir de zarf vardı. Zarfın üstünde sadece bir soru yazıyordu: “En çok neyi merak ediyorsun?”',
        'Nur Hanım açıkladı:',
        '– Tatil boyunca her biriniz kendi merakının peşinden gidecek. Zarfın içinde bir kütüphane kartı var. Merak ettiğiniz konuyla ilgili bir kitap seçip okuyacaksınız. Döndüğünüzde sınıfa anlatacaksınız.',
        'Ben dinozorları merak ediyordum. Arkadaşım Selin denizaltıları, İbrahim ise ünlü ressamları merak ediyordu. Tatilin ilk günü kütüphaneye gittik.',
        'Kütüphaneci bize bir şey öğretti: Her kitabı aynı şekilde okumayız. Bir hikâye kitabını baştan sona keyifle okuruz. Bilgi veren bir kitapta ise önce içindekiler sayfasına bakar, aradığımız bölümü buluruz. Önemli yerlerin altını çizer ya da not alırız. Bir haritaya ya da tabloya bakarken de yavaş ve dikkatli okuruz.',
        'Dinozor kitabımı önce baştan sona karıştırdım. Resimlere baktım, başlıkları okudum. Sonra beni en çok ilgilendiren bölümü, “Dinozorlar neden yok oldu?” bölümünü dikkatle okudum. Bir deftere notlar aldım.',
        'Tatil bitince sınıfa döndük. Herkes merakını anlattı. Selin bir denizaltının nasıl battığını ve yüzeye çıktığını bir pet şişeyle gösterdi. İbrahim ünlü bir ressamın tablosunu kendi elleriyle yeniden çizmişti. Ben de dinozorların neden yok olduğuna dair bilim insanlarının düşüncelerini anlattım.',
        'Nur Hanım hepimize baktı ve gülümsedi:',
        '– Gördünüz mü? Karnedeki notlar bir dönemi anlatır. Ama merak, bütün hayatı anlatır.',
      ] }),
      numarala([harita(), tablo('Hangi kitabı nasıl okuruz? Metne göre doldur.', ['Kitap türü', 'Nasıl okuruz?'], [['Hikâye kitabı', ''], ['Bilgi veren kitap', ''], ['Harita ve tablo', '']]),
        soru(['Nur Hanım\'ın son sözü ne anlatıyor?'])]),
      numarala([siniflandir('Kitap rafı! Kitap adlarını türüne göre doğru rafa yaz.', [['Hikâye', '#f2546b'], ['Bilgi', '#3a86ff'], ['Şiir', '#8b5cf6']], ['Dinozorların Sırrı', 'Ay\'a Giden Kedi', 'Denizaltılar Nasıl Çalışır?', 'Bahar Dizeleri', 'Kayıp Prenses', 'Volkanlar Atlası']),
        tablo('Okuma planım! Bu ay okumak istediğin kitapları yaz.', ['Kitap', 'Neden seçtim?', 'Nasıl okuyacağım?'], [['', '', ''], ['', '', ''], ['', '', '']])]),
      numarala([yazma('En çok neyi merak ediyorsun? Merakının peşine düşmek için bir plan yaz.', ['Merak ettiğim konu:', 'Hangi kaynaklara bakacağım?', 'Öğrendiklerimi nasıl paylaşacağım?'], 12)]),
    ] },
    'hafta-20': { unite: 6, hafta: 20, baslik: 'Kaşıkçı Usta', konu: 'Yeteneklerimizi kullanıyoruz · Çıkarım yapma', sayfalar: () => [
      metin({ baslik: 'Kaşıkçı Usta', resimler: ['kasik-ustasi', 'tahta-kasiklar'], tahmin: 'Resme bak. Bu usta ne yapıyor? Bu meslek kolay mı?', paragraflar: [
        'Babaannemin kasabasında, çarşının en sonunda küçük bir dükkân vardır. Kapısının üstünde tahtadan oyulmuş kocaman bir kaşık asılıdır. Burası Kaşıkçı Hüseyin Usta\'nın dükkânıdır.',
        'Bu yaz bir sabah dükkânın önünden geçerken içeriden gelen tık tık seslerine dayanamadım, içeri girdim. Hüseyin Usta tezgâhının başında oturmuş, elindeki bir şimşir tahtasını yontuyordu. Yerde ince, kıvrım kıvrım talaşlar birikmişti.',
        '– Gel bakalım genç, dedi Usta. Ellerin boş durmasın, şu zımparayı al.',
        'Bütün sabah onu izledim. Önce kaşığın şeklini tahtaya kurşunkalemle çizdi. Sonra küçük bir baltayla fazlalıkları yonttu. Ardından eğri bıçaklarla kaşığın çukurunu oydu. En sonunda zımparayla öyle bir parlattı ki kaşığın yüzeyi ipek gibi oldu.',
        '– Usta, bir kaşık ne kadar sürede biter? diye sordum.',
        '– İki gün, dedi. Ama bu işi öğrenmek kırk yıl sürer.',
        'Ellerine baktım. Parmaklarında küçük yara izleri, avuçlarında nasırlar vardı. Ama elleri tahtaya dokunduğunda bir piyanistin elleri gibi yumuşak ve dikkatliydi.',
        'Öğleye doğru dükkâna yaşlı bir kadın girdi. Elinde kırık bir tahta kaşık vardı.',
        '– Bunu annem kullanırdı, dedi. Düğünümde hediye etmişti. Tamir olur mu?',
        'Hüseyin Usta kaşığı aldı, uzun uzun inceledi. Kırık yeri ince bir tahta parçası ve tutkalla birleştirdi, sonra zımparaladı. Kadın kaşığı geri aldığında gözleri doldu.',
        'Akşam evde babaanneme anlattım. Babaannem mutfaktaki çekmeceyi açtı. İçinde Hüseyin Usta\'nın yaptığı bir kaşık vardı.',
        '– Bunu otuz yıl önce aldım, dedi. Hâlâ ilk günkü gibi.',
      ] }),
      numarala([harita(), etk(0, 'Çıkarım yap! Metinde açıkça yazmıyor ama ipuçlarından ne anlıyoruz? İpucunu ve çıkarımını yaz.', `<table class="h2-tablo ttkb" style="width:100%"><tr><th>İpucu</th><th>Ne anlıyorum?</th></tr>${[['Parmaklarında yara izleri ve nasırlar vardı.', ''], ['Kadının gözleri doldu.', ''], ['Babaannenin kaşığı otuz yıldır duruyor.', '']].map(r => `<tr><td>${r[0]}</td><td style="height:14mm"></td></tr>`).join('')}</table>`)]),
      numarala([sirala(['Kaşığın şeklini tahtaya çizdi.', 'Fazlalıkları baltayla yonttu.', 'Çukuru eğri bıçakla oydu.', 'Zımparayla parlattı.'], 201).replace('Olayları oluş sırasına göre numaralandır.', 'Bir kaşık nasıl yapılır? Adımları sıraya koy.'),
        sozcuk([['Kaşığın yüzeyi <u>ipek gibi</u> oldu.', ['çok yumuşak ve pürüzsüz', 'çok sert', 'kırmızı']], ['Bu işi öğrenmek <u>kırk yıl</u> sürer.', ['çok uzun zaman alır', 'tam kırk yıl sürer', 'kolaydır']]]),
        soru(['Hüseyin Usta\'nın elleri neden "piyanistin elleri" gibi?'])]),
      numarala([yazma('Çevrende bir el ustasını (aşçı, terzi, marangoz, ressam…) gözle ya da onunla konuş. Onu tanıtan bir yazı yaz.', ['Kim, ne yapıyor?', 'Nasıl çalışıyor?', 'Ondan ne öğrendin?'], 12)]),
    ] },
    'hafta-21': { unite: 6, hafta: 21, baslik: 'Satranç Tahtasındaki Kız', konu: 'Yeteneklerimizi kullanıyoruz · Benzetme ve örneklendirme, bilginin kaynağını yazma', sayfalar: () => [
      metin({ baslik: 'Satranç Tahtasındaki Kız', resimler: ['satranc', 'satranc-kupa'], tahmin: 'Satranç oynamak için hangi yetenekler gerekir?', paragraflar: [
        'Beren ilk satranç tahtasını yedi yaşında, dedesinin evinde gördü. Siyah ve beyaz kareler ona bir dama tahtası gibi görünmüştü. Taşlar ise küçük bir ordu gibi karşılıklı dizilmişti.',
        'Dedesi ona taşların nasıl hareket ettiğini öğretti. Kale bir tren gibi dümdüz giderdi. Fil, çapraz yollarda kayan bir kızak gibiydi. At ise en tuhafıydı; “L” harfi çizerek, diğer taşların üstünden atlayarak ilerlerdi. Şah en önemli taştı ama yavaş yürürdü. Vezir ise her yöne gidebilen en güçlü taştı.',
        'Beren ilk maçlarında hep kaybetti. Bir keresinde sinirlenip taşları kutuya geri doldurdu.',
        '– Satranç bana göre değil, dedi.',
        'Dedesi kutuyu yeniden açtı:',
        '– Kaybettiğin her maç sana bir şey öğretir. Bir hatanı not al, bir dahakine yapma. Satranç, sabrın oyunudur.',
        'Beren o gün bir defter tuttu. Her maçtan sonra yaptığı bir hatayı yazdı: “Atımı korumayı unuttum.” “Vezirimi çok erken oynattım.” Defter doldukça hataları azaldı.',
        'Okuldaki satranç kulübüne katıldı. Kulüp öğretmeni ona satranç tarihini anlatan bir kitap verdi. Beren kitaptan satrancın yaklaşık bin beş yüz yıl önce Hindistan\'da ortaya çıktığını, oradan İran\'a ve tüm dünyaya yayıldığını öğrendi. Bunu kulüp panosuna yazdığı yazının altına şöyle not etti: “Kaynak: Satranç kulübü kitaplığı, ‘Satrancın Uzun Yolculuğu’ adlı kitap.”',
        'Bir yıl sonra il satranç turnuvasına katıldı. Son maçta karşısında çok güçlü bir rakip vardı. Beren sakin kaldı, her hamleyi dikkatle düşündü. Ve kazandı!',
        'Kupayı aldığında ilk işi dedesini aramak oldu.',
        '– Dede, defterim işe yaradı! dedi.',
        'Dedesi telefonun öbür ucunda gülümsedi:',
        '– Defterin değil kızım, sabrın işe yaradı.',
      ] }),
      numarala([harita(), eslestir('Metindeki benzetmeleri eşleştir: Hangi taş neye benzetilmiş?', [['Kale', 'kızak gibi'], ['Fil', 'tren gibi'], ['Taşların dizilişi', 'küçük bir ordu gibi']], 211),
        soru(['Beren\'in defteri ona nasıl yardım etti?', 'Dedesinin son sözü ne anlatıyor?'])]),
      numarala([bosluk('Kendi benzetmelerini yap. "gibi" ile tamamla.', ['Satranç tahtası ___ gibi.', 'Beren\'in sabrı ___ gibi.', 'Turnuva salonu ___ gibi sessizdi.']),
        etk(0, 'Bilginin kaynağını yaz! Beren\'in yazısında kaynağı nasıl gösterdiğine bak. Sen de bir bilgi ve kaynağını yaz.', `<div class="t3-sozluk ttkb"><div><b>Öğrendiğim bilgi:</b>${cizgi(2)}</div><div><b>Kaynak (kitap ya da site adı):</b>${cizgi(1)}</div></div>`),
        soru(['Bir yeteneğini geliştirmek için ne yapabilirsin? Bir örnek ver.'])]),
      numarala([yazma('Geliştirmek istediğin bir yetenek için "hata defteri" planı yaz. Neyi deneyecek, nasıl ilerleyeceksin?', ['Yeteneğim:', 'Şu an zorlandığım şey:', 'Planım:'], 12)]),
    ] },
    'hafta-22': { unite: 6, hafta: 22, baslik: 'Rüzgârı Yakalayan Kız', konu: 'Yeteneklerimizi kullanıyoruz · Açıklayıcı yazı, dijital sunum', sayfalar: () => [
      metin({ baslik: 'Rüzgârı Yakalayan Kız', resimler: ['mucit-kiz', 'parkta-kosu'], tahmin: 'Rüzgâr yakalanabilir mi? Bu kız ne yapıyor olabilir?', paragraflar: [
        'Zehra\'nın köyü bir tepenin üstündeydi ve orada rüzgâr hiç durmazdı. Çamaşırlar ipte dans eder, kapılar kendi kendine çarpardı. Herkes rüzgârdan şikâyet ederdi. Zehra ise bir gün şunu düşündü: “Bu kadar rüzgâr boşa mı esiyor?”',
        'Bilim ve Teknoloji Haftası\'nda öğretmeni Murat Bey sınıfa bir video izletti. Videoda dev beyaz pervaneler dönüyordu: rüzgâr türbinleri. Murat Bey, türbinlerin rüzgârın gücünü elektriğe çevirdiğini anlattı.',
        'Zehra o akşam bir proje yapmaya karar verdi. Eski bir bisiklet dinamosu, plastik şişelerden kestiği pervaneler ve tahta bir çubukla küçük bir türbin yaptı. İlk denemede pervaneler döndü ama ampul yanmadı. İkinci denemede kablolar koptu. Üçüncü denemede pervaneleri daha geniş kesti ve türbini tepenin en rüzgârlı yerine koydu.',
        'Ve küçük ampul titreyerek yandı!',
        'Zehra ertesi gün projesini okula götürdü. Murat Bey onu okul bilim şenliğine katılmaya davet etti. Zehra bir sunum hazırladı. Bilgisayarda türbinin fotoğraflarını, çizimlerini ve nasıl çalıştığını anlatan kısa yazıları düzenledi. Her bilginin altına nereden öğrendiğini yazdı.',
        'Şenlikte Zehra\'nın standı çok kalabalıktı. Bir çocuk sordu:',
        '– Rüzgâr dinerse ne olur?',
        'Zehra gülümsedi:',
        '– O zaman güneşten yardım alırız. Bir gün köyümüze hem rüzgâr hem güneş enerjisi getirmek istiyorum.',
        'Şenlik bitince köye döndü. Çamaşırlar yine ipte dans ediyordu. Ama Zehra artık rüzgârı başka bir gözle görüyordu: Bir şikâyet değil, bir hazine.',
      ] }),
      numarala([harita(), sirala(['Zehra rüzgâr türbinlerini videoda gördü.', 'Şişelerden pervane yaptı.', 'İlk iki denemede başaramadı.', 'Ampul yandı.', 'Bilim şenliğinde projesini sundu.'], 221),
        soru(['Zehra rüzgâra neden "hazine" diyor?', 'Zehra başarısız olduğunda ne yaptı?'])]),
      numarala([etk(0, 'Dijital sunum planı! Zehra gibi bir proje sunumu hazırlayacaksın. Her slaytta ne olacağını yaz ya da çiz.', `<div class="t3-ucbolum ttkb">${['1. slayt: Proje adı', '2. slayt: Nasıl çalışır?', '3. slayt: Kaynaklarım'].map(s => `<div><b>${s}</b>${cizgi(4)}</div>`).join('')}</div>`),
        fikir('Bu düşünceye katılıyor musun?', 'Başarısız olmak, başarıya giden yolun bir parçasıdır.')]),
      numarala([yazma('Rüzgâr ya da güneş enerjisini anlatan açıklayıcı bir yazı yaz. Bilgilerin kaynağını da belirt.', ['Nedir?', 'Nasıl elektrik üretilir?', 'Faydaları nelerdir?'], 12)]),
    ] },
    'hafta-23': { unite: 7, hafta: 23, baslik: 'Nusret\'in Gece Yolculuğu', konu: 'Bilim yolculuğu · Ön bilgilerle bağlantı kurma, olay sırası', sayfalar: () => [
      metin({ baslik: 'Nusret\'in Gece Yolculuğu', resimler: ['bogaz-gunbatimi', 'dolma-kalem'], tahmin: 'Küçük bir gemi büyük bir zafere nasıl katkı sağlayabilir?', paragraflar: [
        '1915 yılının mart ayı. Çanakkale Boğazı\'nın önünde dünyanın en güçlü donanmalarından birinin gemileri bekliyordu. Amaçları boğazı geçip İstanbul\'a ulaşmaktı.',
        'Boğazın içinde ise küçük, sessiz bir gemi vardı: Nusret. Nusret bir mayın gemisiydi. Görevi denizin altına mayın döşemekti. Ama boğaza daha önce döşenen mayınlar düşman gemilerince temizlenmeye başlanmıştı.',
        'Nusret\'in komutanı ve mürettebatı bir gözlem yaptı: Düşman gemileri her gün Erenköy Koyu\'na girip orada dönüyordu. Bu koyun bir yeri, düşmanın dikkatinden kaçmıştı.',
        '7 Mart\'ı 8 Mart\'a bağlayan gece, Nusret ışıklarını söndürdü. Karanlığın içinde, düşman projektörlerinin arasından sessizce süzüldü. Mürettebat nefesini tutmuştu. Erenköy Koyu\'na ulaşınca, düşmanın beklemediği bir hatta, kıyıya paralel 26 mayını tek tek denize bıraktı. Sonra yine sessizce geri döndü.',
        'Günler geçti. 18 Mart sabahı düşman donanması büyük bir saldırı başlattı. Gemiler boğaza girdi, Erenköy Koyu\'nda dönmeye başladı. İşte tam o sırada Nusret\'in mayınları birer birer patladı! Birçok büyük gemi battı ya da ağır yara aldı. Düşman donanması geri çekildi.',
        'Bu, Çanakkale Deniz Zaferi\'ydi. Bugün her yıl 18 Mart\'ta bu zaferi ve şehitlerimizi saygıyla anıyoruz.',
        'Nusret\'in bir benzeri bugün Çanakkale\'de müze gemi olarak ziyaretçileri bekliyor. Onu görenler, küçük bir geminin dikkatli gözlem, cesaret ve sessiz bir çalışmayla nasıl büyük bir iş başardığını öğreniyor.',
      ] }),
      numarala([harita(), sirala(['Düşman gemilerinin Erenköy Koyu\'nda döndüğü fark edildi.', 'Nusret gece ışıklarını söndürüp yola çıktı.', 'Koya 26 mayın döşendi.', '18 Mart\'ta düşman gemileri mayınlara çarptı.', 'Düşman donanması geri çekildi.'], 231),
        soru(['Nusret\'in başarısında gözlemin payı neydi?', 'Daha önce Çanakkale hakkında neler biliyordun? Bu metin bilgilerine ne ekledi?'])]),
      numarala([tablo('Ön bilgimle bağlantı! Çanakkale hakkında bildiklerini ve yeni öğrendiklerini yaz.', ['Önceden biliyordum', 'Yeni öğrendim', 'Merak ediyorum'], [['', '', ''], ['', '', ''], ['', '', '']]),
        sozcuk([['Nusret düşman <u>projektörlerinin</u> arasından süzüldü.', ['uzağı aydınlatan güçlü ışıklar', 'gemiler', 'dalgalar']], ['<u>Mürettebat</u> nefesini tutmuştu.', ['gemide çalışan kişiler', 'yolcular', 'balıklar']]])]),
      numarala([yazma('18 Mart Çanakkale Zaferi için okul panosuna bir yazı hazırla. Nusret\'in hikâyesini kendi cümlelerinle anlat.', ['Ne zaman, nerede?', 'Nusret ne yaptı?', 'Bu olay bize ne öğretiyor?'], 12)]),
    ] },
    'hafta-24': { unite: 7, hafta: 24, baslik: 'Uzaydan Gelen Cevap', konu: 'Bilim yolculuğu · Deyim ve atasözü, gerçek ve mecaz anlam', sayfalar: () => [
      metin({ baslik: 'Uzaydan Gelen Cevap', resimler: ['uzay-istasyonu', 'astronot-cocuk'], tahmin: 'Uzaydaki bir astronota mektup yazsan ne sorardın?', paragraflar: [
        'Ocak ayında televizyonda bir haber izledik: İlk Türk astronot uzaya gidiyordu! Uluslararası Uzay İstasyonu\'nda iki hafta kalacak, deneyler yapacaktı. Sınıfta herkesin ağzı kulaklarına vardı.',
        'Öğretmenimiz Selin Hanım bir öneride bulundu:',
        '– Haydi, bir astronota mektup yazalım. Belki bir gün cevap verir.',
        'Herkes sorusunu yazdı. Ben şunu sordum: “Uzayda uyurken yatağınızdan uçup gitmiyor musunuz?” Arkadaşım Can ise “Uzayda yemek nasıl yeniyor?” diye sordu. Mektupları bir zarfa koyup bilim merkezine gönderdik.',
        'Aylar geçti. Bir gün okul müdürümüz elinde bir zarfla sınıfa girdi. Zarfın üzerinde bir uzay roketi resmi vardı! Bir bilim merkezinden geliyordu. İçinde bir mektup ve uzaydan çekilmiş bir dünya fotoğrafı vardı.',
        'Mektupta bir uzay bilimcisi bizim sorularımızı cevaplamıştı. Uzayda yerçekimi olmadığı için astronotların uyku tulumlarını duvara bağlayarak uyuduğunu yazıyordu. Yemekler özel paketlerdeydi; ekmek yerine pide gibi yassı ekmekler kullanılıyordu çünkü ekmek kırıntıları havada uçuşup aletlere zarar verebiliyordu.',
        'Mektubun sonunda şu satırlar vardı: “Uzaydan dünyaya bakınca ülkeler arasında sınır görünmüyor. Mavi bir top, beyaz bulutlar… Hepimiz aynı evde yaşıyoruz. Bilim insanı olmak isteyenler, unutmayın: Damlaya damlaya göl olur. Her gün biraz öğrenin.”',
        'Fotoğrafı sınıf panosuna astık. Can fotoğrafa bakıp gözlerini kırpmadan uzun uzun izledi. Sonra bana döndü:',
        '– Ben büyüyünce o istasyona gideceğim, dedi.',
        'Selin Hanım duymuştu. Gülümsedi:',
        '– Hayal kurmak işin yarısıdır Can. Kalan yarısı çalışmak.',
      ] }),
      numarala([harita(), soru(['Astronotlar uzayda nasıl uyur?', 'Uzayda neden ekmek yerine yassı ekmek kullanılır?', 'Mektuptaki "Hepimiz aynı evde yaşıyoruz." sözü ne anlatıyor?'])]),
      numarala([gercekMecaz(['Can\'ın <u>ağzı kulaklarına vardı</u>.', 'Astronot <u>uzaya</u> gitti.', 'Bu haber bizi <u>uçurdu</u>.', 'Kuşlar gökyüzünde <u>uçuyor</u>.']),
        eslestir('Deyim ve atasözlerini anlamlarıyla eşleştir.', [['Damlaya damlaya göl olur.', 'çok sevinmek'], ['Ağzı kulaklarına varmak', 'küçük birikimler büyür'], ['Gözünü kırpmadan bakmak', 'çok dikkatle bakmak']], 241)]),
      numarala([yazma('Bir bilim insanına ya da astronota bir mektup yaz. Ona merak ettiğin soruları sor. En az bir deyim kullan.', ['Hitap:', 'Kendini tanıt ve sorularını sor:', 'Kapanış:'], 12)]),
    ] },
    'hafta-25': { unite: 7, hafta: 25, baslik: 'Saati Taşıyan Fil', konu: 'Bilim yolculuğu · Farklı öneriler sunma, açıklayıcı metin', sayfalar: () => [
      metin({ baslik: 'Saati Taşıyan Fil', resimler: ['fil-saati', 'cark-model'], tahmin: 'Bir fil saat taşıyabilir mi? Bu saat nasıl çalışıyor olabilir?', paragraflar: [
        'Kütüphaneler Haftası\'nda kütüphanede eski bir kitabın kopyasını gördük. Kitap yaklaşık sekiz yüz yıl önce yazılmıştı ve içi rengârenk makine çizimleriyle doluydu. Yazarı, Cizre\'de yaşamış büyük bir mucitti: El-Cezerî.',
        'Kütüphaneci bize kitabın en ünlü sayfasını açtı. Sayfada sırtında süslü bir kule taşıyan bir fil vardı. Bu, El-Cezerî\'nin icat ettiği “fil saati”ydi.',
        'Fil saati nasıl çalışıyordu? Filin karnında içi su dolu bir kap vardı. Bu kabın içinde de dibinde küçük bir delik olan bir tas yüzüyordu. Delikten yavaş yavaş su giren tas, tam yarım saatte dolup batıyordu. Tas battığında bağlı olduğu ipler bir düzeneği çekiyordu. Kulenin tepesindeki bir top, bir yılanın ağzına düşüyor; yılan eğiliyor, bir figür davul çalıyordu. Böylece herkes yarım saatin geçtiğini anlıyordu. Sonra tas kendiliğinden yukarı çıkıyor ve her şey yeniden başlıyordu.',
        'El-Cezerî sadece saat yapmamıştı. Su pompaları, kendi kendine çalışan çeşmeler, el yıkamaya yarayan su dökücüler gibi pek çok makine tasarlamıştı. Bazı bilim insanları onu, kendi kendine çalışan makinelerin, yani robotların ilk öncülerinden biri olarak görür.',
        'Öğretmenimiz bize bir soru sordu:',
        '– El-Cezerî bugün yaşasaydı ne icat ederdi sizce?',
        'Herkes bir şey söyledi. Biri “Su tasarrufu yapan bir musluk.” dedi, biri “Ödev yapan bir robot!” Hepimiz güldük. Ben de “Ağaç diken bir makine.” dedim.',
        'Eve dönünce kâğıttan dişliler kesip birbirine taktım. Biri dönünce öteki de dönüyordu. Küçük bir makine yapmıştım. Belki de bütün büyük icatlar böyle küçük bir merakla başlıyordu.',
      ] }),
      numarala([harita(), sirala(['Tasın dibindeki delikten su girer.', 'Tas yarım saatte dolar ve batar.', 'İpler düzeneği çeker.', 'Top yılanın ağzına düşer.', 'Figür davul çalar.'], 251).replace('Olayları oluş sırasına göre numaralandır.', 'Fil saati nasıl çalışır? Adımları sıraya koy.'),
        soru(['Fil saati yarım saatin geçtiğini nasıl haber veriyordu?', 'El-Cezerî\'ye neden robotların öncülerinden biri deniyor?'])]),
      numarala([etk(0, 'Farklı öneriler sun! El-Cezerî bugün yaşasaydı ne icat ederdi? Üç farklı öneri yaz ve her birinin neye yarayacağını açıkla.', `<div class="t3-ucbolum ttkb">${['1. öneri', '2. öneri', '3. öneri'].map(s => `<div><b>${s}</b>${cizgi(4)}</div>`).join('')}</div>`),
        sozcuk([['El-Cezerî bir <u>düzenek</u> tasarladı.', ['birlikte çalışan parçalardan oluşan alet', 'resim', 'kitap']], ['O, robotların <u>öncülerinden</u> biridir.', ['ilk yapanlardan, yol açanlardan', 'sonuncularından', 'düşmanlarından']]])]),
      numarala([yazma('Kendi icadını tasarla! Adını koy, nasıl çalıştığını ve neye yaradığını açıklayan bir yazı yaz.', ['İcadımın adı:', 'Nasıl çalışır?', 'Kimin işine yarar?'], 12)]),
    ] },
    'hafta-26': { unite: 7, hafta: 26, baslik: 'Yıldızları Sayan Adam', konu: 'Bilim yolculuğu · Gerçek ve mecaz anlam, okuma stratejisi', sayfalar: () => [
      metin({ baslik: 'Yıldızları Sayan Adam', resimler: ['eski-gozlemevi', 'teleskoplu-cocuk'], tahmin: 'Eskiden insanlar yıldızları nasıl inceliyordu?', paragraflar: [
        'Yaklaşık altı yüz yıl önce, Semerkant şehrinde büyük bir gözlemevi vardı. Bu gözlemevini bilim âşığı bir hükümdar olan Uluğ Bey yaptırmıştı. Gözlemevinde yıldızların, gezegenlerin, Güneş\'in ve Ay\'ın hareketlerini inceleyen bilginler çalışırdı.',
        'Bu bilginlerden biri, genç ve meraklı bir öğrenciydi: Ali Kuşçu. Adının bir hikâyesi vardı. Babası Uluğ Bey\'in doğancısıydı, yani avcı kuşlarına bakardı. Kuşçu adı buradan geliyordu. Ama Ali\'nin gözü kuşlarda değil, yıldızlardaydı.',
        'Ali Kuşçu her gece gözlemevinin kulesine çıkar, saatlerce gökyüzünü izlerdi. O zamanlar teleskop yoktu. Bilginler yıldızları büyük taş ve bakır aletlerle ölçerdi. Ali Kuşçu ve arkadaşları binlerce yıldızın yerini tek tek ölçüp bir kitaba yazdılar. Bu yıldız kataloğu, yüzyıllar boyunca bilim insanlarının kullandığı bir hazine oldu.',
        'Ali Kuşçu ayrıca matematik ve astronomi kitapları yazdı. Yıllar sonra İstanbul\'a geldi ve burada ders verdi. Öğrencilerine şöyle derdi:',
        '– Gökyüzü büyük bir kitaptır. Onu okumak için önce sabırla bakmayı öğrenmelisiniz.',
        'Bugün Ay\'da bir kraterin adı Ali Kuşçu\'dur. Gökyüzünü okuyan adamın adı, artık gökyüzünde yazılıdır.',
        'Geçen yaz dedemle köyde, ışıkların az olduğu bir tepede yıldızlara baktık. Dedem bana Büyük Ayı\'yı gösterdi. Ben de ona Ali Kuşçu\'yu anlattım. Dedem gülümsedi:',
        '– Demek sen de yıldızları saymaya başladın.',
      ] }),
      numarala([harita(), dogruYanlis(['Gözlemevini Uluğ Bey yaptırdı.', 'Ali Kuşçu yıldızları teleskopla inceledi.', 'Ali Kuşçu ve arkadaşları bir yıldız kataloğu hazırladı.', 'Ay\'daki bir kratere Ali Kuşçu\'nun adı verildi.']),
        soru(['Ali Kuşçu\'nun "Gökyüzü büyük bir kitaptır." sözü ne anlatıyor?'])]),
      numarala([gercekMecaz(['Ali\'nin <u>gözü</u> yıldızlardaydı.', 'Astronom <u>gözünü</u> alete dayadı.', 'Gökyüzü büyük bir <u>kitaptır</u>.', 'Kütüphaneden bir <u>kitap</u> aldım.', 'Bu haber bana <u>soğuk</u> geldi.', 'Gece hava çok <u>soğuktu</u>.']),
        tablo('Bu metni nasıl okudum? Okuma stratejini değerlendir.', ['Strateji', 'Kullandım mı?'], [['Önce başlık ve resimlere bakıp tahmin yaptım.', ''], ['Bilmediğim sözcükleri not aldım.', ''], ['Önemli bilgilerin altını çizdim.', '']])]),
      numarala([yazma('Bir gece gökyüzünü gözle. Gördüklerini bir bilim insanı gibi not al ve anlatan bir yazı yaz.', ['Ne zaman, nereden baktın?', 'Neler gördün? (Ay, yıldız, gezegen…)', 'Neyi merak ettin?'], 12)]),
    ] },
    'hafta-27': { unite: 7, hafta: 27, baslik: 'Bir Damlanın Yolculuğu', konu: 'Bilim yolculuğu · Veri okuma, okuma tercihi', sayfalar: () => [
      metin({ baslik: 'Bir Damlanın Yolculuğu', resimler: ['su-dongusu', 'yagmur-olcer'], tahmin: 'Bir su damlası nerelere yolculuk yapar?', paragraflar: [
        'Merhaba! Ben bir su damlasıyım. Adım Damla. Bugün sana bitmeyen yolculuğumu anlatacağım.',
        'Uzun zaman önce koca bir okyanusun içindeydim. Bir gün güneş beni öyle ısıttı ki hafifledim, hafifledim ve görünmez bir buhar olarak havaya yükseldim. Buna buharlaşma denir.',
        'Yükseldikçe hava soğudu. Benim gibi milyonlarca buhar taneciği bir araya geldi ve minik damlacıklara dönüştük. Birlikte bembeyaz bir bulut olduk. Buna da yoğuşma denir.',
        'Rüzgâr bulutumuzu dağlara doğru sürükledi. Damlacıklar birleştikçe ağırlaştık. Sonunda bulut bizi taşıyamadı ve yağmur olarak yere düştük. Dağın tepesinde hava çok soğuksa kar olarak da düşebiliriz. Buna yağış denir.',
        'Ben bir dağın yamacına düştüm. Toprağın içine sızdım, bir ağacın köklerine uğradım. Sonra bir derede arkadaşlarımla buluştum. Dere bir nehre, nehir de denize aktı. Ve ben yine okyanustaydım!',
        'Bu yolculuğa su döngüsü denir. Bu döngü milyonlarca yıldır sürüyor. Belki şu an içtiğin suyun içinde, bir zamanlar bir dinozorun içtiği damlalar vardır!',
        'Ama dikkat! Dünyadaki suyun çok büyük bir kısmı tuzludur. İçebileceğimiz tatlı su ise çok azdır. Bu yüzden her damla değerlidir.',
        'Okulumuzda bir yağmur ölçer kurduk. Her hafta ne kadar yağmur yağdığını ölçüp bir tabloya yazıyoruz. Geçen ay en çok yağmur ikinci hafta yağdı. Belki o yağmurda ben de vardım. Kim bilir?',
      ] }),
      numarala([harita('Metni incele.'), etk(0, 'Su döngüsünün aşamalarını sırayla yaz ve açıkla.', `<div class="t3-sozluk ttkb">${['1. Buharlaşma:', '2. Yoğuşma:', '3. Yağış:', '4. Toplanma (dere, nehir, deniz):'].map(s => `<div><b>${s}</b>${cizgi(1)}</div>`).join('')}</div>`)]),
      numarala([etk(0, 'Okulun yağmur ölçeri! Tabloyu oku ve soruları cevapla.', `<table class="h2-tablo ttkb" style="width:100%"><tr><th>Hafta</th><th>1. hafta</th><th>2. hafta</th><th>3. hafta</th><th>4. hafta</th></tr><tr><td>Yağmur (mm)</td><td>12</td><td>30</td><td>8</td><td>18</td></tr></table><div class="t2-soru">${['En çok yağmur hangi hafta yağdı?', 'En az yağmur hangi hafta yağdı?', 'Dördüncü hafta, üçüncü haftadan kaç milimetre fazla yağmur yağdı?'].map(s => `<div><p class="ttkb">${s}</p>${cizgi(1)}</div>`).join('')}</div>`),
        fikir('Bu düşünceye katılıyor musun?', 'Su döngüsü olduğu için suyu istediğimiz kadar harcayabiliriz.')]),
      numarala([yazma('Sen bir kar tanesi olsaydın yolculuğun nasıl olurdu? Bilgileri kullanarak hayal gücüyle bir hikâye yaz.', ['Nerede doğdun?', 'Nerelere gittin?', 'Yolculuğun nasıl bitti?'], 12)]),
    ] },
    'hafta-28': { unite: 8, hafta: 28, baslik: 'Perdenin Ardındaki Gölgeler', konu: 'Millî kültürümüz · Görüş bildirme, görsellerle öyküleme', sayfalar: () => [
      metin({ baslik: 'Perdenin Ardındaki Gölgeler', resimler: ['golge-oyunu', 'bayram-gecidi'], tahmin: 'Perdenin arkasında gölgeler nasıl oynar?', paragraflar: [
        '23 Nisan için okulumuzda bir kültür şenliği düzenlendi. Her sınıf bir geleneğimizi tanıtacaktı. Bizim sınıfa gölge oyunu düştü: Karagöz ile Hacivat.',
        'Öğretmenimiz bize bir gölge oyunu ustası davet etti. Usta Mehmet Bey elinde bir bavulla geldi. Bavulu açtığında içinden rengârenk, düz figürler çıktı. Figürler deve derisinden yapılmıştı ve ışığa tutunca camdan gibi parlıyorlardı.',
        '– Bu Karagöz, dedi Usta, siyah sakallı figürü göstererek. Saf, dobra ve biraz da sabırsızdır. Bu da Hacivat. Kibar konuşur, bilgiçlik taslar. İkisi hiç anlaşamaz ama birbirlerinden de vazgeçemezler.',
        'Usta bize perdeyi kurdu. Beyaz bir bez, arkasında bir lamba… Figürleri ince sopalarla perdeye bastırınca gölgeleri canlandı. Karagöz zıpladı, Hacivat eğilip selam verdi. Usta iki karakterin sesini de kendisi çıkarıyordu!',
        '– Hacivat: Ah, Karagöz\'üm, nerelerdesin, seni çok özledim!',
        '– Karagöz: Ben de seni özledim ama borcunu hâlâ ödemedin!',
        'Bütün sınıf kahkahalarla güldü. Usta, Karagöz ile Hacivat\'ın yüzyıllardır insanları hem güldürdüğünü hem düşündürdüğünü anlattı. Oyunlardaki karışıklıklar hep bir yanlış anlamadan çıkardı ve sonunda herkes ders çıkarırdı.',
        'Şenlik günü biz de kendi gölge oyunumuzu oynadık. Kartondan figürler kesmiş, perdeyi bir çarşaftan yapmıştık. Konumuz 23 Nisan\'dı: Karagöz bayram için okulu süslemek istiyor, Hacivat ise ona nasıl süsleneceğini anlatmaya çalışıyordu. Seyirciler çok eğlendi.',
        'Oyun bittiğinde perdeyi kaldırdık. Arkasında heyecandan yanakları kızarmış beş çocuk vardı. Gölgeler yine gelenekti, oyuncular ise yeniydi.',
      ] }),
      numarala([harita(), kiyas('Karagöz ile Hacivat\'ı karşılaştır.', 'Karagöz', 'Hacivat'),
        soru(['Son cümledeki "Gölgeler yine gelenekti, oyuncular ise yeniydi." ne anlatıyor?'])]),
      numarala([fikir('Bu düşünceye katılıyor musun?', 'Gölge oyunu eskide kaldı, bugün kimse izlemez.'),
        etk(0, 'Katılmadığın bir görüşe öneri yaz: Bir arkadaşın "Geleneksel oyunlar sıkıcıdır." diyor. Ona kibarca karşı çık ve bir öneride bulun.', cizgi(4))]),
      numarala([etk(0, 'Görsellerle öykü! Kendi gölge oyununu dört karede çiz, her karenin altına bir konuşma yaz.', `<div class="t3-dortkare">${[1, 2, 3, 4].map(i => `<div><span>${i}</span><i></i>${cizgi(2)}</div>`).join('')}</div>`)]),
    ] },
    'hafta-29': { unite: 8, hafta: 29, baslik: 'Suyun Üstündeki Lale', konu: 'Millî kültürümüz · Farklı öneriler sunma, emek', sayfalar: () => [
      metin({ baslik: 'Suyun Üstündeki Lale', resimler: ['ebru-usta', 'ebru-lale'], tahmin: 'Su üstüne resim yapılabilir mi? Tahmin et.', paragraflar: [
        'Emek ve Dayanışma Günü\'nde sınıfça bir ebru atölyesini ziyaret ettik. Atölye eski bir taş binanın içindeydi. İçeride mis gibi bir kitre kokusu vardı. Ortada uzun bir tekne, teknenin içinde koyu ve kıvamlı bir su duruyordu.',
        'Ebru ustası Nesrin Hanım bizi gülümseyerek karşıladı.',
        '– Ebru, su üstüne resim yapma sanatıdır, dedi. Bu suya kitre denen bir bitkinin özünü karıştırdık. Böylece su koyulaşır ve boyalar batmadan üstünde yüzer.',
        'Nesrin Hanım ince bir fırçayı boyaya batırdı. Sonra fırçaya hafifçe vurarak boyayı suyun üstüne serpti. Kırmızı, mavi, sarı benekler suyun yüzeyine yayıldı. Sonra ince bir iğneyle boyaların arasında dolaşmaya başladı. İğnenin değdiği yerde renkler kıvrıldı, birbirine sarıldı. Birkaç dakika içinde suyun üstünde kocaman bir lale açtı!',
        'Hepimiz nefesimizi tutmuştuk. Nesrin Hanım teknenin üstüne beyaz bir kâğıt yavaşça bıraktı. Birkaç saniye bekledi. Sonra kâğıdı bir kenarından tutup kaldırdı. Lale artık kâğıdın üstündeydi!',
        '– Usta, bunu öğrenmek ne kadar sürdü? diye sordu Emir.',
        '– Ustamın yanında on yıl çalıştım, dedi Nesrin Hanım. İlk yıl sadece boya ezdim, fırça yaptım. Ustam, “Önce emeğe saygıyı öğren.” derdi.',
        'Sonra her birimize kendi ebrumuzu yapma fırsatı verdi. Benim boyalarım dağıldı, lalem bir yağmur bulutuna benzedi. Ama Nesrin Hanım güldü:',
        '– Ebruda iki eser asla aynı olmaz. Seninki de dünyada tek.',
        'Okula dönünce ebrumu sınıf panosuna astık. Altına şunu yazdım: “Suyun üstündeki bulut. Emeği: Ben ve Nesrin Hanım.”',
      ] }),
      numarala([harita(), sirala(['Suya kitre karıştırılır.', 'Boyalar suyun üstüne serpilir.', 'İğneyle desen oluşturulur.', 'Kâğıt suyun üstüne bırakılır.', 'Kâğıt kaldırılır.'], 291).replace('Olayları oluş sırasına göre numaralandır.', 'Ebru nasıl yapılır? Adımları sıraya koy.'),
        soru(['Ustanın "Önce emeğe saygıyı öğren." sözü ne anlatıyor?', 'Neden iki ebru asla aynı olmaz?'])]),
      numarala([etk(0, 'Farklı öneriler! Ebru sanatını daha çok çocuğa sevdirmek için üç farklı öneri yaz.', `<div class="t3-ucbolum ttkb">${['1. öneri', '2. öneri', '3. öneri'].map(s => `<div><b>${s}</b>${cizgi(4)}</div>`).join('')}</div>`),
        eslestir('Atasözlerini anlamlarıyla eşleştir.', [['Emek olmadan yemek olmaz.', 'Sabırla çalışan sonunda başarır.'], ['Sabrın sonu selamettir.', 'Çalışmadan kazanılmaz.'], ['Bir elin nesi var, iki elin sesi var.', 'Birlikte çalışmak işi kolaylaştırır.']], 292)]),
      numarala([yazma('Bir el sanatını (çini, ebru, kilim, oya, ahşap oyma…) araştır ve tanıtan bir yazı yaz. Bilginin kaynağını da yaz.', ['Sanatın adı ve nasıl yapıldığı:', 'Neden değerli?', 'Kaynağım:'], 12)]),
    ] },
    'hafta-30': { unite: 8, hafta: 30, baslik: 'Tandırın Başında', konu: 'Millî kültürümüz · Okuma amacına göre okuma, yardımlaşma', sayfalar: () => [
      metin({ baslik: 'Tandırın Başında', resimler: ['yufka-imece', 'tandir'], tahmin: 'İmece ne demek olabilir?', paragraflar: [
        'Anneler Günü haftasında annemle anneannemin köyüne gittik. Köyde o gün büyük bir hazırlık vardı: Kış için yufka açılacaktı. Anneannem bu işe “imece” dedi. İmece, köydekilerin bir işi el birliğiyle, sırayla yapmasıydı.',
        'Sabah erkenden Gülsüm Teyze\'nin avlusunda toplandık. Avlunun köşesinde topraktan yapılmış, içinde ateşin yandığı bir tandır vardı. Kadınlar yere minderler serdi, ortaya yuvarlak tahtalar koydu.',
        'Herkesin bir görevi vardı. Gülsüm Teyze hamuru yoğurdu. Hamur o kadar büyüktü ki iki kişi ancak çevirebiliyordu. Annem ve teyzelerim hamurdan bezeler kopardı. Anneannem uzun bir oklavayla bezeleri incecik açtı. Açılan yufkalar öyle inceydi ki arkasından eli görünüyordu. Sonra yufkalar sac üzerinde ya da tandırda pişirildi.',
        'Benim görevim pişen yufkaları üst üste dizmekti. Bir de tandırın başındaki büyüklere su taşıyordum. Bir ara ben de oklavayı denedim. Yufkam bir harita gibi delik deşik oldu. Herkes güldü ama anneannem beni övdü:',
        '– İlk yufkam da böyleydi kızım. El alışır.',
        'Öğleye doğru kadınlar türküler söylemeye başladı. Bir yandan hamur açıyor, bir yandan şakalaşıyorlardı. Yorgunluk sanki uçup gitmişti.',
        'Akşam olduğunda yüzlerce yufka hazırdı. Yufkalar köydeki her eve eşit paylaştırıldı. Hiç yufkası olmayan yaşlı Rıza Dede\'ye de bir tepsi götürüldü.',
        'Eve dönerken anneme sordum:',
        '– Herkes kendi yufkasını neden kendisi açmıyor?',
        'Annem gülümsedi:',
        '– Tek başına açsan bir hafta sürer. Birlikte açınca bir gün. Hem bir günde yalnız yufka değil, dostluk da pişer.',
      ] }),
      numarala([harita(), tablo('İmecede kim ne yaptı? Metne göre doldur.', ['Kim?', 'Görevi'], [['Gülsüm Teyze', ''], ['Anneanne', ''], ['Anlatıcı', ''], ['Bütün köy', '']]),
        soru(['Annenin "Bir günde dostluk da pişer." sözü ne anlatıyor?'])]),
      numarala([tablo('Okuma amacım! Aşağıdaki metinleri hangi amaçla ve nasıl okursun?', ['Metin', 'Amacım', 'Nasıl okurum?'], [['Bir yufka tarifi', 'Yapmayı öğrenmek', ''], ['Bir masal', '', 'Baştan sona, keyifle'], ['Bir otobüs saati tablosu', '', '']]),
        sozcuk([['Hamurdan <u>bezeler</u> koparıldı.', ['yuvarlak hamur parçaları', 'tahta parçaları', 'kaplar']], ['Bu işi <u>el birliğiyle</u> yaptık.', ['birlikte, yardımlaşarak', 'tek elle', 'eldivenle']]])]),
      numarala([yazma('Annene ya da sana bakan bir büyüğüne birlikte yaptığınız bir işi hatırlatan bir Anneler Günü mektubu yaz.', ['Hitap:', 'Birlikte ne yapmıştınız, nasıl hissettin?', 'Dilek ve kapanış:'], 12)]),
    ] },
    'hafta-31': { unite: 8, hafta: 31, baslik: 'Halay Halkası', konu: 'Millî kültürümüz · Görüşe katılıp katılmama, nedenlerini yazma', sayfalar: () => [
      metin({ baslik: 'Halay Halkası', resimler: ['halk-oyunu', 'davul-zurna'], tahmin: 'Halk oyunlarında insanlar neden el ele tutuşur?', paragraflar: [
        'Okulumuzun halk oyunları ekibi bahar şenliğine hazırlanıyordu. Öğretmenimiz Hakan Bey bu yıl Sivas halayı çalışacağımızı söyledi. Ben önce pek istekli değildim. Dans etmeyi beceremeyeceğimi düşünüyordum.',
        'İlk prova günü spor salonuna girdiğimizde davulcu ve zurnacı amcalar bizi bekliyordu. Davul “güm güm” diye vurmaya başlayınca kalbim de onunla birlikte atmaya başladı. Zurnanın sesi salonu doldurdu.',
        'Hakan Bey bizi yan yana dizdi.',
        '– Halayda serçe parmaklarımızla birbirimize tutunuruz, dedi. Omuz omuza dururuz. Birimiz yanlış adım atarsa halka bozulur. Bu yüzden yanımızdakini hissetmeli, onunla birlikte hareket etmeliyiz.',
        'İlk günler sürekli yanlış adım attım. Sağ ayağım sola, sol ayağım sağa gidiyordu. Yanımdaki Esra her seferinde serçe parmağıyla elimi hafifçe sıktı. Bu, “Şimdi sağa!” demekti. Yavaş yavaş adımları öğrendim.',
        'Bir prova sonrası Hakan Bey bize halayların hikâyesini anlattı. Her bölgenin halayı farklıydı. Kiminde ayak vuruşları sertti, kiminde omuzlar titrerdi. Düğünlerde, bayramlarda, hasattan sonra insanlar halaya dururdu. Halay, sevinci paylaşmanın bir yoluydu.',
        'Şenlik günü geldi. Renkli yöresel kıyafetlerimizi giydik. Davul vurmaya başladı. Halka döndü, döndü… Bir an seyircilere baktım. Annem, babam, dedem… Dedem yerinden kalkmış, seyircilerden birkaç kişiyle birlikte kendi halkasını kurmuştu!',
        'Gösteri bitince Hakan Bey yanıma geldi:',
        '– Gördün mü? Halay bir kişinin dansı değil, herkesin dansıdır. Sen de artık halkanın bir parçasısın.',
      ] }),
      numarala([harita(), soru(['Esra serçe parmağıyla anlatıcıya nasıl yardım etti?', 'Hakan Bey\'e göre halay neden "herkesin dansı"dır?']),
        sozcuk([['Halay, sevinci <u>paylaşmanın</u> bir yoluydu.', ['başkalarıyla birlikte yaşamanın', 'saklamanın', 'unutmanın']]])]),
      numarala([fikir('Bu düşünceye katılıyor musun? Nedenleriyle yaz.', 'Halk oyunları sadece büyükler içindir.'),
        fikir('Bu düşünceye katılıyor musun? Nedenleriyle yaz.', 'Bir işi birlikte yapmak, tek başına yapmaktan daha zevklidir.'),
        etk(0, 'Katılmadığın bir görüşe öneri yaz: Arkadaşın "Ben dans edemem, hiç denemeyeceğim." diyor. Ona ne önerirsin?', cizgi(3))]),
      numarala([yazma('Ailende ya da çevrende yaşatılan bir geleneği anlat (halay, düğün, bayram, hıdrellez…).', ['Gelenek nedir?', 'Nasıl yapılır?', 'Senin için anlamı ne?'], 12)]),
    ] },
    'hafta-32': { unite: 9, hafta: 32, baslik: 'Masmavi Testi', konu: 'Hak ve sorumluluklarımız · Pekiştirmeli sözcükler, noktalamanın anlama etkisi', sayfalar: () => [
      metin({ baslik: 'Masmavi Testi', resimler: ['muzede-cocuklar', 'genclik-kosusu'], tahmin: 'Müzedeki eski bir testi bize neler anlatabilir?', paragraflar: [
        'Müzeler Haftası\'nda sınıfça arkeoloji müzesine gittik. Müzenin kapısında bizi tertemiz, bembeyaz önlüklü bir rehber karşıladı.',
        '– Müzeler, geçmişin hafızasıdır, dedi. Burada gördüğünüz her eşya bir zamanlar birinin elindeydi. Birlikte o insanların hikâyesini dinleyeceğiz.',
        'İlk salonda kapkara toprak çanaklar, sapsarı altın küpeler ve yemyeşil cam şişeler vardı. Ama beni en çok etkileyen, camlı bir dolabın içindeki masmavi bir testi oldu. Testinin üstünde balık resimleri vardı ve kenarı biraz kırılmıştı.',
        'Rehber testinin hikâyesini anlattı. Bu testi binlerce yıl önce bir çömlekçi tarafından yapılmıştı. Belki bir ailenin su testisiydi. Belki bir çocuk her sabah onunla çeşmeden su taşıyordu. Kenarındaki kırık, belki de o çocuğun bir gün testiyi düşürmesiyle oluşmuştu.',
        '– Peki bu testi bize nasıl ulaştı? diye sordu Emre.',
        '– Arkeologlar onu toprağın altında buldu, dedi rehber. Bulunca çok dikkatli temizlediler, kaydettiler ve buraya getirdiler. Şimdi onu korumak hepimizin sorumluluğu. Müzede eşyalara dokunmayız, flaşla fotoğraf çekmeyiz, koşmayız. Böylece bu testi bizden sonraki çocuklara da ulaşır.',
        'Müzeden çıkarken bir şey fark ettim. Testinin önünde dururken o çocuğu düşünmüş, onunla konuşur gibi olmuştum. Müze, sadece eski eşyaların durduğu bir yer değildi. Zamanda yolculuk yapılan bir yerdi.',
        'Ertesi gün 19 Mayıs\'tı. Okulda bayram coşkusu vardı. Gençlik ve Spor Bayramı törenine katıldık. Tören bittiğinde öğretmenimiz bir soru sordu: “Bin yıl sonra biri bizim okulumuzda bir eşya bulsa, neyi bulmasını isterdiniz?” Ben hiç düşünmeden cevap verdim: “Bugünkü bayram fotoğrafımızı.”',
      ] }),
      numarala([harita(), dogruYanlis(['Müzede masmavi bir testi vardı.', 'Testiyi bir çiftçi tarlada buldu.', 'Müzede flaşla fotoğraf çekmeyiz.', 'Anlatıcıya göre müze zamanda yolculuk yapılan bir yerdir.']),
        soru(['Müzede hangi hak ve sorumluluklarımız vardır?'])]),
      numarala([eslestir('Pekiştirmeli sözcükleri eşleştir. (Pekiştirme, anlamı güçlendirir: mavi → masmavi)', [['mavi', 'bembeyaz'], ['beyaz', 'kapkara'], ['kara', 'masmavi'], ['yeşil', 'sapsarı'], ['sarı', 'yemyeşil']], 321),
        bosluk('Pekiştirmeli sözcüklerle tamamla. Yazımına dikkat et.', ['Gökyüzü ___ idi. (mavi)', 'Bahçedeki çimenler ___ idi. (yeşil)', 'Elbisesi ___ ve temizdi. (beyaz)']),
        etk(0, 'Noktalama anlamı değiştirir! İki cümleyi oku. Aralarındaki anlam farkını yaz.', `<div class="t2-soru">${[['Testi kırıldı.', 'Testi kırıldı mı?'], ['Rehber geldi!', 'Rehber geldi.']].map(([a, b]) => `<div><p class="ttkb">“${a}” ile “${b}”</p>${cizgi(1)}</div>`).join('')}</div>`)]),
      numarala([yazma('Bin yıl sonra müzede sergilenecek bir eşyan olsaydı ne olurdu? O eşyanın hikâyesini yaz. En az iki pekiştirmeli sözcük kullan.', ['Eşyan ne?', 'Hikâyesi ne?', 'Gelecekteki çocuklara ne anlatsın?'], 12)]),
    ] },
    'hafta-33': { unite: 9, hafta: 33, baslik: 'Çocuk Meclisi', konu: 'Hak ve sorumluluklarımız · Ayrıntılı yönerge, çevrim içi okuma', sayfalar: () => [
      metin({ baslik: 'Çocuk Meclisi', resimler: ['cocuk-meclisi', 'oy-sandigi'], tahmin: 'Çocuklar bir meclis kursa neleri konuşur?', paragraflar: [
        'İlçemizde her yıl bir “Çocuk Meclisi” toplanır. Her okuldan seçilen çocuklar belediye binasında bir araya gelir, çocukları ilgilendiren konuları konuşur. Bu yıl okulumuzu temsil etmek için sınıfımızda bir seçim yapıldı.',
        'Önce aday olmak isteyenler kısa bir konuşma yaptı. Elif okul bahçesine daha çok ağaç dikilmesini istedi. Barış kütüphanenin hafta sonu da açık olmasını önerdi. Ben de okul önündeki yaya geçidine bir trafik ışığı konmasını istedim. Sonra oylama yapıldı. Her öğrenci bir kâğıda tek bir isim yazdı ve şeffaf sandığa attı. Oyları birlikte saydık. Elif seçildi.',
        'Elif, Çocuk Meclisi\'ne gitmeden önce sınıfça bir hazırlık yaptık. Hepimizin önerilerini bir listeye yazdık. Bu listeyi nasıl sunacağımızı planladık. Öğretmenimiz bize, bir öneriyi sunarken önce sorunu, sonra nedenlerini, en son da çözümü anlatmamızı söyledi.',
        'Meclis günü Elif kürsüye çıktı. Sesi önce biraz titredi ama sonra güçlendi. Okul önündeki tehlikeli yaya geçidinden, sabahları yaşanan kalabalıktan bahsetti. Çözüm olarak bir trafik ışığı ve bir okul geçidi görevlisi önerdi.',
        'Belediye başkanı Elif\'i dikkatle dinledi. Diğer okullardan gelen çocuklar da benzer sorunlardan söz etti. Meclisin sonunda başkan, bütün okulların önündeki yaya geçitlerinin kontrol edileceğini söyledi.',
        'İki ay sonra okulumuzun önüne bir trafik ışığı kondu. Elif bize koşarak geldi:',
        '– Bakın! Bizim önerimiz!',
        'O gün anladım ki çocukların da söz hakkı vardı. Ama bu hakkı kullanmak bir sorumluluk da getiriyordu: dinlemek, düşünmek ve önerimizi düzgün anlatmak.',
      ] }),
      numarala([harita(), sirala(['Sınıfta adaylar konuşma yaptı.', 'Oylama yapıldı ve Elif seçildi.', 'Sınıf önerileri listeledi.', 'Elif mecliste öneriyi sundu.', 'Okulun önüne trafik ışığı kondu.'], 331),
        soru(['Öğretmene göre bir öneri hangi sırayla sunulmalı?', 'Anlatıcıya göre söz hakkı hangi sorumlulukları getirir?'])]),
      numarala([yonergeYaz('Ayrıntılı yönerge! Sınıfta bir seçimin nasıl yapılacağını adım adım yaz. Her adımda neye dikkat edileceğini de ekle.', 5),
        tablo('İnternette okurken de kitap okurken yaptığımız gibi davranırız. Hangilerini yaparsın?', ['Davranış', 'Kitapta', 'İnternette'], [['Okumadan önce başlığa bakarım.', '', ''], ['Bilginin kaynağını kontrol ederim.', '', ''], ['Önemli bilgiyi not alırım.', '', ''], ['Dikkatimi dağıtan şeylere tıklamam.', '', '']])]),
      numarala([yazma('Çocuk Meclisi\'ne bir öneri sun! Önce sorunu, sonra nedenlerini, en son çözümünü yaz.', ['Sorun:', 'Nedenleri:', 'Çözüm önerim:'], 12)]),
    ] },
    'hafta-34': { unite: 9, hafta: 34, baslik: 'Kaplumbağanın Yolu', konu: 'Hak ve sorumluluklarımız · Konu ve ana fikir, noktalama ve anlam', sayfalar: () => [
      metin({ baslik: 'Kaplumbağanın Yolu', resimler: ['plastik-deniz', 'sahil-temizlik'], tahmin: 'Bir deniz kaplumbağası denizde nelerle karşılaşır?', paragraflar: [
        'Her yaz ailemle gittiğimiz kumsal, deniz kaplumbağalarının yumurtladığı bir kumsaldır. Geceleri anne kaplumbağalar denizden çıkar, kuma çukur kazıp yumurtalarını bırakır. Yaklaşık iki ay sonra yavrular yumurtadan çıkar ve hep birlikte denize doğru koşar.',
        'Bu yaz bir gönüllü grubu kumsalda yuvaları koruyordu. Grubun başında deniz biyoloğu Deniz Abla vardı. Bizi de gönüllü olarak aldı. Görevimiz yuvaların etrafına küçük kafesler koymak ve geceleri kumsalda ışık yakılmamasını sağlamaktı.',
        '– Neden ışık yakılmamalı? diye sordum.',
        '– Çünkü yavrular denize ulaşmak için ayın ve yıldızların denizdeki parıltısını takip eder, dedi Deniz Abla. Otellerin ve evlerin ışıkları onları şaşırtır, yanlış yöne giderler.',
        'Bir sabah Deniz Abla bize üzücü bir şey gösterdi. Kıyıya vurmuş bir plastik poşeti eline aldı.',
        '– Kaplumbağalar denizanası yer. Suyun içinde yüzen bir poşet, onlara denizanası gibi görünür. Yutarlarsa hastalanırlar.',
        'O gün kumsalda bir temizlik yaptık. Bir saatte üç büyük çuval dolusu plastik topladık: şişeler, kapaklar, pipetler, poşetler… En çok da küçük plastik parçaları vardı.',
        'Ağustosun sonunda bir gece Deniz Abla bizi uyandırdı. Yuvalardan biri açılıyordu! Kumun içinden minicik kafalar çıktı. Yüzlerce yavru kaplumbağa paytak paytak denize koştu. Ay ışığı denizi gümüş gibi parlatıyordu. Son yavru da dalgaların arasında kaybolduğunda hepimiz alkışladık.',
        'Eve döndüğümüzde kendi kendime bir söz verdim: Artık pipet kullanmayacak, alışverişe bez çantayla gidecektim. Çünkü denizdeki her poşet, bir kaplumbağanın yolunu kapatabilirdi.',
      ] }),
      numarala([harita(), etk(0, 'Konu ve ana fikir! Metnin konusunu ve ana fikrini yaz.', `<div class="t3-sozluk ttkb"><div><b>Konu (metin ne hakkında?):</b>${cizgi(1)}</div><div><b>Ana fikir (yazar ne demek istiyor?):</b>${cizgi(2)}</div></div>`),
        soru(['Yavrular denize ulaşmak için neyi takip eder?', 'Kaplumbağalar poşetleri neden yutar?'])]),
      numarala([etk(0, 'Noktalama ve anlam! Cümlelerin sonundaki işaretler yazarın hangi duygusunu gösteriyor? Yaz.', `<div class="t2-soru">${['Yuvalardan biri açılıyordu!', 'Neden ışık yakılmamalı?', 'Bir saatte üç çuval plastik topladık.'].map(s => `<div><p class="ttkb">${s}</p>${cizgi(1)}</div>`).join('')}</div>`),
        tablo('Plastik dedektifi! Bir gün boyunca kullandığın plastikleri say ve yerine ne kullanabileceğini yaz.', ['Plastik', 'Kaç tane?', 'Yerine ne kullanabilirim?'], [['Pipet', '', ''], ['Poşet', '', ''], ['Pet şişe', '', '']])]),
      numarala([yazma('Denizleri korumak için bir sözleşme hazırla. Kendine ve ailene üç söz ver.', ['1. sözüm:', '2. sözüm:', '3. sözüm:'], 12)]),
    ] },
    'hafta-35': { unite: 10, hafta: 35, baslik: 'Okul Gazetemiz', konu: 'Okul temelli planlama · Haber yazma, yazma ortamı', sayfalar: () => [
      metin({ baslik: 'Okul Gazetemiz', resimler: ['okul-gazetesi', 'duyuru-panosu'], tahmin: 'Bir okul gazetesinde neler yazar?', paragraflar: [
        'Yılın son ayında sınıfımız bir okul gazetesi çıkarmaya karar verdi. Gazetenin adını oylamayla seçtik: “Ladin Haber”. Herkes bir görev aldı. Kimimiz muhabir, kimimiz fotoğrafçı, kimimiz çizer oldu. Ben de muhabirlerden biriydim.',
        'İlk haberim için okulun yeni güneş panellerini seçtim. Öğretmenimiz bize haber yazmanın kurallarını öğretti:',
        '– İyi bir haber altı soruya cevap verir: Ne oldu? Kim yaptı? Nerede oldu? Ne zaman oldu? Nasıl oldu? Neden oldu?',
        'Okul müdürümüzle bir söyleşi yaptım. Bir deftere sorularımı önceden yazmıştım. Müdürümüz panellerin okulun elektriğinin bir kısmını güneşten karşıladığını anlattı. Fotoğrafçımız Bora çatıya çıkamadı ama bahçeden panellerin güzel bir fotoğrafını çekti.',
        'Haberimi yazmak için sessiz bir yer aradım. Sınıf çok gürültülüydü, aklımı toplayamıyordum. Kütüphaneye gittim. Pencerenin önündeki masaya oturdum. Sessizlik ve güneş ışığı bana iyi geldi. Önce bir taslak yazdım. Sonra okudum, gereksiz cümleleri sildim, eksikleri ekledim. Başlığı en sona bıraktım: “Okulumuz Artık Güneşle Çalışıyor!”',
        'Diğer sayfalarda bir bilmece köşesi, en sevdiğimiz kitaplar, öğretmenlerimizle söyleşiler ve sınıfımızın en komik anları vardı. Çizerimiz Elif her sayfaya küçük resimler çizdi.',
        'Gazetenin ilk sayısını fotokopiyle çoğalttık ve okul panosuna astık. Teneffüste panonun önünde kalabalık bir grup birikti. Bir dördüncü sınıf öğrencisi haberimi okurken gülümsedi. O an kendimi gerçek bir gazeteci gibi hissettim.',
      ] }),
      numarala([harita(), tablo('Altı soru! Anlatıcının haberini altı soruya göre doldur.', ['Soru', 'Cevap'], [['Ne oldu?', ''], ['Kim?', ''], ['Nerede?', ''], ['Ne zaman?', ''], ['Nasıl?', ''], ['Neden?', '']])]),
      numarala([tablo('Yazma ortamım! Yazı yazarken nerede ve nasıl daha iyi yazarsın?', ['Ortam', 'Bana iyi gelir mi? Neden?'], [['Sessiz bir oda', ''], ['Gürültülü bir sınıf', ''], ['Pencere kenarı', ''], ['Televizyonun yanı', '']]),
        soru(['Anlatıcı yazısını nasıl düzeltti? (taslak, okuma, silme, ekleme)', 'Başlığı neden en sona bırakmış olabilir?'])]),
      numarala([yazma('Okulunda ya da sınıfında olan bir olayı haber olarak yaz. Altı soruyu cevapla ve dikkat çekici bir başlık koy.', ['Ne, kim, nerede?', 'Ne zaman, nasıl?', 'Neden önemli?'], 12)]),
    ] },
    'hafta-36': { unite: 10, hafta: 36, baslik: 'Üçüncü Sınıfın Son Sayfası', konu: 'Pekiştirme haftası · Yılın tekrarı', sayfalar: () => [
      metin({ baslik: 'Üçüncü Sınıfın Son Sayfası', resimler: ['okulun-son-gunu', 'yaz-plani'], tahmin: 'Yılın son günü sınıfta neler olur?', paragraflar: [
        'Haziranın son haftasıydı. Sınıfın penceresinden yaz kokusu giriyordu. Öğretmenimiz Nur Hanım rafın en üstünden eylülde koyduğu “Sınıf Hatıra Kutusu”nu indirdi. Hepimiz nefesimizi tuttuk.',
        'Kutuyu açtı. İçinde her aydan anılar vardı. Eylülde yazdığımız ilk kâğıtlar, ekimde Hatice Nine ile yaptığım söyleşi, ocakta kütüphanede geçirdiğimiz gecenin fotoğrafları, şubatta Zehra\'nın rüzgâr türbininin çizimi, martta Nusret\'i anlattığımız pano yazısı, nisanda gölge oyunumuzun karton figürleri, haziranda okul gazetemizin ilk sayısı…',
        'Nur Hanım kâğıtları tek tek okudu. Bazılarına güldük, bazılarında duygulandık. Sonra eylülde yazdığım ilk anımı bana uzattı. Yazım ne kadar da farklıydı! Cümlelerim kısacıktı, bir iki yerde büyük harfi unutmuştum. Şimdi ise sayfalar dolusu yazabiliyordum. Hem de giriş, gelişme ve sonuç bölümleriyle.',
        '– Bir yıl önce kim olduğunuza bakın, dedi Nur Hanım. Şimdi kim olduğunuza bakın. İşte bu farka “büyümek” diyoruz.',
        'Sonra hepimize birer kâğıt verdi. Bu kez dördüncü sınıftaki kendimize birer mektup yazacaktık. Ben şöyle yazdım:',
        '“Sevgili gelecekteki ben, bu yıl çok şey öğrendim: Bir sözlükte kaybolmayı, bir dilekçe yazmayı, bir halaya katılmayı. En çok da şunu öğrendim: Merak etmek, her şeyin başlangıcıdır. Sen de merakını hiç kaybetme. Sevgilerle, üçüncü sınıftaki sen.”',
        'Mektuplarımızı zarflara koyduk, kutuya yerleştirdik. Nur Hanım kutuyu kapatıp üstüne yazdı: “Eylülde açılacak.”',
        'Zil çaldı. Okul bahçesinde birbirimize sarıldık, iyi tatiller diledik. Kapıdan çıkarken arkama dönüp sınıfa son bir kez baktım. Bu bir son değildi. Sadece bir kitabın son sayfasıydı. Eylülde yeni bir kitap açılacaktı.',
      ] }),
      numarala([harita(), tablo('Hatıra kutusundan neler çıktı? Ayları ve anıları eşleştirerek yaz.', ['Ay', 'Anı'], [['Eylül', ''], ['Ocak', ''], ['Mart', ''], ['Nisan', '']]),
        soru(['Nur Hanım\'a göre "büyümek" ne demek?'])]),
      numarala([yeniden('Yılın tekrarı! Her cümlede bir hata var: büyük harf, kısaltma eki, soru eki ya da noktalama. Düzelterek yaz.', ['nur hanım kutuyu açtı.', 'TBMM\'ne bir mektup yazdık.', 'Sen de merakını kaybetmedinmi?']),
        domino('Eş, zıt ya da pekiştirme? Boş yarıya uygun sözcüğü yaz ve türünü belirt.', ['son', 'yanıt', 'mavi', 'kısa', 'büyümek', 'temiz'], ['ilk', 'cevap', 'masmavi', 'uzun', 'gelişmek', 'tertemiz']),
        gercekMecaz(['Bu bir kitabın son <u>sayfasıydı</u>.', 'Defterimin son <u>sayfasına</u> yazdım.'])]),
      numarala([yazma('Dördüncü sınıftaki kendine bir mektup yaz. Bu yıl ne öğrendiğini, neyi merak ettiğini ve gelecek yıl için dileklerini anlat.', ['Hitap:', 'Bu yıl öğrendiklerim ve merak ettiklerim:', 'Dileklerim ve kapanış:'], 12)]),
    ] },
  };
  const CSS = `
.t3-sec{display:flex;flex-direction:column;gap:2mm}.t3-sec span{background:#fff;border:.5mm solid #9db4c8;border-radius:3mm;padding:2mm 3mm;font-size:5mm}
.t3-not{margin:3mm 0 0;font-size:5mm}
.t3-gm{display:flex;flex-direction:column;gap:2.5mm}.t3-gm>div{display:flex;align-items:center;gap:4mm;background:#fff;border-radius:3mm;padding:2mm 3mm}.t3-gm p{margin:0;flex:1;font-size:5mm}
.t3-gm span{display:flex;align-items:center;gap:1.5mm;font-size:4.6mm}.t3-gm i{width:6mm;height:6mm;border:.5mm solid #4a5a50;border-radius:1.5mm}
.t3-gm u{text-decoration-thickness:.5mm;text-underline-offset:1mm;color:#c2410c}
.t3-imza{display:flex;flex-direction:column;gap:3mm;background:#fff;border-radius:3mm;padding:3mm}.t3-imza>div{display:grid;grid-template-columns:40mm 1fr;align-items:end;gap:2mm}.t3-imza span{font-size:5mm}.t3-imza i{height:22mm;border-bottom:.45mm dashed #9db4c8}
.t3-sirala{display:grid;grid-template-columns:repeat(3,1fr);gap:3mm}.t3-sirala span{display:flex;align-items:center;gap:2mm;background:#fff;border-radius:3mm;padding:2mm 3mm;font-size:5.4mm}.t3-sirala i{width:9mm;height:9mm;border:.5mm solid #4a5a50;border-radius:50%}
.t3-sozluk{display:flex;flex-direction:column;gap:2mm}.t3-sozluk>div{background:#fff;border-radius:3mm;padding:2mm 3mm}.t3-sozluk b{font-weight:400;font-size:5.2mm;color:#1d4e89}
.t3-ucbolum{display:grid;grid-template-columns:repeat(3,1fr);gap:3mm}.t3-ucbolum>div{background:#fff;border-radius:3mm;padding:2mm 3mm}.t3-ucbolum b{font-weight:400;font-size:5mm;color:#8b5cf6}
.t3-dortkare{display:grid;grid-template-columns:1fr 1fr;gap:4mm;flex:1}.t3-dortkare>div{background:#fff;border-radius:3mm;padding:2mm 3mm;display:flex;flex-direction:column;gap:1mm;position:relative}.t3-dortkare span{position:absolute;top:2mm;left:3mm;font-size:5mm;color:#8b5cf6}.t3-dortkare i{flex:1;min-height:44mm;border:.5mm dashed #9db4c8;border-radius:2mm}
.t3-dilekce{background:#fff;border-radius:3mm;padding:4mm 6mm;font-size:5mm}.t3-dilekce p{margin:0 0 2mm}.t3-sag{text-align:right}.t3-orta{text-align:center;text-transform:uppercase}.t3-konu{font-size:4.6mm;color:#5b6b7b}
`;
  return { T3, CSS };
};
